\label{lemma-flat}
Let $M$ be an $R$-module. The following are equivalent:
\begin{enumerate}
\item
\label{item-flat}
$M$ is flat over $R$.
\item
\label{item-injective}
for every injection of $R$-modules $N \subset N'$
the map $N \otimes_R M \to N'\otimes_R M$ is injective.
\item
\label{item-f-ideal}
for every ideal $I \subset R$ the map
$I \otimes_R M \to R \otimes_R M = M$ is injective.
\item
\label{item-ffg-ideal}
for every finitely generated ideal $I \subset R$
the map $I \otimes_R M \to R \otimes_R M = M$ is injective.
\end{enumerate}

\label{lemma-sober-subspace}
Let $X$ be a topological space and let $Y\subset X$.
\begin{enumerate}
\item If $X$ is Kolmogorov then so is $Y$.
\item Suppose $Y$ is locally closed in $X$. If $X$ is quasi-sober then
so is $Y$.
\item Suppose $Y$ is locally closed in $X$. If $X$ is sober then so is $Y$.
\end{enumerate}

\label{lemma-profinite-refine-open-covering}
Let $X$ be a profinite space. Every open covering of $X$ has a refinement
by a finite covering $X = \coprod U_i$ with $U_i$ open and closed.

\label{proposition-oka}
If $\mathcal{F}$ is an Oka family of ideals, then any maximal element of
the complement of $\mathcal{F}$ is prime.

\label{lemma-affine}
\begin{slogan}
A scheme, admitting a finite surjective map from an affine scheme, is affine.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
Assume that $f$ is surjective and finite, and assume that $X$ is affine.
Then $S$ is affine.

\label{lemma-constructible-neighbourhood-Noetherian}
Let $X$ be a Noetherian topological space.
Let $x \in X$.
Let $E \subset X$ be constructible in $X$.
The following are equivalent:
\begin{enumerate}
\item $E$ is a neighbourhood of $x$, and
\item for every irreducible closed subset $Y$ of $X$ which contains
$x$ the intersection $E \cap Y$ is dense in $Y$.
\end{enumerate}

\label{lemma-descend-surjective}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is surjective, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is surjective.

\label{proposition-exist-ordinals-large-cofinality}
Let $\kappa$ be a cardinal. Then there exists an ordinal
whose cofinality is bigger than $\kappa$.

\label{lemma-descend-finite-locally-free}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is finite locally free (of degree $d$),
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is finite locally free (of degree $d$) for some $i \geq 0$.

\label{lemma-descend-dimension-d}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ has relative dimension $d$, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$
has relative dimension $d$.

\label{lemma-purely-inseparable-elements}
Let $E/k$ be a field extension. Then the elements of $E$ purely-inseparable
over $k$ form a subextension of $E/k$.

\label{lemma-reduced-ring-sub-product-fields}
Let $R$ be a reduced ring. Then
\begin{enumerate}
\item $R$ is a subring of a product of fields,
\item $R \to \prod_{\mathfrak p\text{ minimal}} R_{\mathfrak p}$
is an embedding into a product of fields,
\item $\bigcup_{\mathfrak p\text{ minimal}} \mathfrak p$ is the set
of zerodivisors of $R$.
\end{enumerate}

\label{lemma-relative-inertia-as-fibre-product}
Let $F : \mathcal{S} \to \mathcal{S}'$ be a $1$-morphism of categories
fibred over a category $\mathcal{C}$. Then the diagram
$$
\xymatrix{
\mathcal{I}_{\mathcal{S}/\mathcal{S}'}
\ar[d]_{F \circ (\ref{equation-inertia-structure-map})}
\ar[rr]_{(\ref{equation-comparison})} & &
\mathcal{I}_\mathcal{S} \ar[d]^{(\ref{equation-functorial})} \\
\mathcal{S}' \ar[rr]^e & &
\mathcal{I}_{\mathcal{S}'}
}
$$
is a $2$-fibre product.

\label{lemma-polynomial-domain-normal}
Let $R$ be a normal domain.
Then $R[x]$ is a normal domain.

\label{lemma-jacobson-equivalent-locally-closed}
\begin{slogan}
For Jacobson spaces, closed points see everything about the topology.
\end{slogan}
Suppose $X$ is a Jacobson topological space.
Let $X_0$ be the set of closed points of $X$.
There is a bijective, inclusion preserving correspondence
$$
\{\text{finite unions loc. closed subsets of } X\}
\leftrightarrow
\{\text{finite unions loc. closed subsets of } X_0\}
$$
given by $E \mapsto E \cap X_0$. This correspondence preserves
the subsets of locally closed, of open and of closed subsets.

\label{lemma-separated-permanence}
Permanence properties.
\begin{enumerate}
\item A composition of separated morphisms is separated.
\item A composition of quasi-separated morphisms is quasi-separated.
\item The base change of a separated morphism is separated.
\item The base change of a quasi-separated morphism is quasi-separated.
\item A (fibre) product of separated morphisms is separated.
\item A (fibre) product of quasi-separated morphisms is quasi-separated.
\end{enumerate}

\label{lemma-characterize-normal}
Let $E/F$ be an algebraic extension of fields. Let $\overline{F}$ be an
algebraic closure of $F$. The following are equivalent
\begin{enumerate}
\item $E$ is normal over $F$, and
\item for every pair $\sigma, \sigma' \in \Mor_F(E, \overline{F})$ we
have $\sigma(E) = \sigma'(E)$.
\end{enumerate}

\label{lemma-subfields-kummer}
\begin{reference}
\cite[Theorem 5.2]{Radical}
\end{reference}
Let $K$ be a field. Let $L/K$ be a finite extension of degree $e$
which is generated by an element $\alpha$ with $a = \alpha^e \in K$.
If every $e$th root of unity in $L$ is contained in $K$, then 
any sub extension $L/L'/K$ is generated by $\alpha^d$ for some $d | e$.

\label{lemma-cover-module}
Let $R$ be a ring. Let $f_1, \ldots, f_n$ be elements of $R$
generating the unit ideal. Let $M$ be an $R$-module.
The sequence
$$
0 \to
M \xrightarrow{\alpha}
\bigoplus\nolimits_{i = 1}^n M_{f_i} \xrightarrow{\beta}
\bigoplus\nolimits_{i, j = 1}^n M_{f_i f_j}
$$
is exact, where $\alpha(m) = (m/1, \ldots, m/1)$
and $\beta(m_1/f_1^{e_1}, \ldots, m_n/f_n^{e_n})
= (m_i/f_i^{e_i} - m_j/f_j^{e_j})_{(i, j)}$.

\label{lemma-characterize-domain}
Let $R$ be a ring.
\begin{enumerate}
\item An ideal maximal among the ideals which do not contain a
nonzerodivisor is prime.
\item If $R$ is nonzero and every nonzero prime ideal in $R$
contains a nonzerodivisor, then $R$ is a domain.
\end{enumerate}

\label{lemma-primes-principal}
Let $R$ be a ring.
\begin{enumerate}
\item An ideal $I \subset R$ maximal with respect to not being
principal is prime.
\item If every prime ideal of $R$ is principal, then
every ideal of $R$ is principal.
\end{enumerate}

\label{lemma-trace-and-norm-tower}
Let $M/L/K$ be a tower of finite extensions of fields. Then
$$
\text{Trace}_{M/K} = \text{Trace}_{L/K} \circ \text{Trace}_{M/L}
\quad\text{and}\quad
\text{Norm}_{M/K} = \text{Norm}_{L/K} \circ \text{Norm}_{M/L}
$$

\label{lemma-base-change-diagonal}
Let
$$
\xymatrix{
\mathcal{U} \ar[d] \ar[r] & \mathcal{V} \ar[d] \\
\mathcal{X} \ar[r] & \mathcal{Y}
}
$$
be a $2$-fibre product of categories. Then the diagram
$$
\xymatrix{
\mathcal{U} \ar[d] \ar[r] &
\mathcal{U} \times_\mathcal{V} \mathcal{U} \ar[d] \\
\mathcal{X} \ar[r] &
\mathcal{X} \times_\mathcal{Y} \mathcal{X}
}
$$
is $2$-cartesian.

\label{lemma-NL-up-to-qis}
In the situation above there is a canonical isomorphism
$\NL(\alpha) = \NL_{\mathcal{B}/\mathcal{A}}$ in $D(\mathcal{B})$.

\label{lemma-cofinal-in-filtered}
\begin{reference}
\cite[Proposition 3.2.4]{KS}
\end{reference}
Let $\mathcal{I}$ be a category. Let $\mathcal{J}$ be a full subcategory.
Assume that $\mathcal{I}$ is filtered. Assume also that for any object
$i$ of $\mathcal{I}$, there exists a morphism $i \to j$
to some object $j$ of $\mathcal{J}$. Then $\mathcal{J}$
is filtered and cofinal in $\mathcal{I}$.

\label{lemma-glue}
\begin{slogan}
If you have two locally ringed spaces, and a subspace of the first one
is isomorphic to a subspace of the other, then you can glue them together
into one big locally ringed space.
\end{slogan}
Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

\label{lemma-partition-refined-by-stratification}
Let $X$ be a topological space. Let $X = \coprod X_i$ be a finite partition
of $X$. Then there exists a finite stratification of $X$ refining it.

\label{lemma-fibre-products-equalizers-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Connected finite limits exist in $\mathcal{C}$.
\item Equalizers and fibre products exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-limit-fibre-product-empty}
In Situation \ref{situation-descent}.
Suppose we are given an $i$ and a morphism $T \to S_i$ such that
\begin{enumerate}
\item $T \times_{S_i} S = \emptyset$, and
\item $T$ is quasi-compact.
\end{enumerate}
Then $T \times_{S_i} S_{i'} = \emptyset$ for all sufficiently large $i'$.

\label{lemma-finite-jacobson}
A finite Jacobson space is discrete.
A Jacobson space with finitely many closed points is discrete.

\label{lemma-spec-spectral}
The spectrum of a ring is a spectral space, see Topology, Definition
\ref{topology-definition-spectral-space}.

\label{lemma-image-dense-generic-points}
Let $R \to S$ be a ring map. The following are equivalent:
\begin{enumerate}
\item The kernel of $R \to S$ consists of nilpotent elements.
\item The minimal primes of $R$ are in the image of
$\Spec(S) \to \Spec(R)$.
\item The image of $\Spec(S) \to \Spec(R)$ is dense
in $\Spec(R)$.
\end{enumerate}

\label{lemma-algebraic-closure-in-finitely-generated}
Let $K/k$ be a finitely generated field extension.
The algebraic closure of $k$ in $K$ is finite over $k$.

\label{lemma-support-zero}
\begin{slogan}
A module over a ring has empty support if and only if it is the trivial module.
\end{slogan}
Let $R$ be a ring. Let $M$ be an $R$-module. Then
$$
M = (0) \Leftrightarrow \text{Supp}(M) = \emptyset.
$$

\label{lemma-constructions-invertible}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item If $\mathcal{L}$, $\mathcal{N}$ are invertible
$\mathcal{O}_X$-modules, then so is
$\mathcal{L} \otimes_{\mathcal{O}_X} \mathcal{N}$.
\item If $\mathcal{L}$ is an invertible $\mathcal{O}_X$-module, then so is
$\SheafHom_{\mathcal{O}_X}(\mathcal{L}, \mathcal{O}_X)$ and the evaluation map
$\mathcal{L} \otimes_{\mathcal{O}_X}
\SheafHom_{\mathcal{O}_X}(\mathcal{L}, \mathcal{O}_X) \to \mathcal{O}_X$
is an isomorphism.
\end{enumerate}

\label{lemma-graph-closed}
\begin{slogan}
Graphs of maps to Hausdorff spaces are closed.
\end{slogan}
Let $f : X \to Y$ be a continuous map of topological spaces.
If $Y$ is Hausdorff, then the graph of $f$ is closed in $X \times Y$.

\label{lemma-support-finite-type-closed}
\begin{slogan}
Over any ringed space, sheaves of modules of finite type have closed support.
\end{slogan}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be a sheaf of $\mathcal{O}_X$-modules.
If $\mathcal{F}$ is of finite type then support of $\mathcal{F}$ is closed.

\label{lemma-irreducible}
Let $X$ be a topological space.
\begin{enumerate}
\item If $T \subset X$ is irreducible so is its closure in $X$.
\item Any irreducible component of $X$ is closed.
\item Any irreducible subset of $X$ is contained in an
irreducible component of $X$.
\item Every point of $X$ is contained in some irreducible component
of $X$, in other words, $X$ is the union of its irreducible components.
\end{enumerate}

\label{lemma-locally-finite-type-in-finite-presentation}
Let $f : X \to S$ be a morphism of schemes.
Assume:
\begin{enumerate}
\item The morphism $f$ is locally of finite type.
\item The scheme $X$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a morphism of finite presentation
$f' : X' \to S$ and an immersion $X \to X'$ of schemes over $S$.

\label{lemma-ideal-is-squared-union-connected}
Let $I \subset R$ be a finitely generated ideal of a ring $R$
such that $I = I^2$. Then
\begin{enumerate}
\item there exists an idempotent $e \in R$ such that $I = (e)$,
\item $R/I \cong R_{e'}$ for the idempotent $e' = 1 - e \in R$, and
\item $V(I)$ is open and closed in $\Spec(R)$.
\end{enumerate}

\label{lemma-descend-smooth}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is smooth,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is smooth for some $i \geq 0$.

\label{lemma-closed-union-connected-components}
Let $X$ be a topological space.
Assume
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of two quasi-compact opens is quasi-compact.
\end{enumerate}
For a subset $T \subset X$ the following are equivalent:
\begin{enumerate}
\item[(a)] $T$ is an intersection of open and closed subsets of $X$, and
\item[(b)] $T$ is closed in $X$ and is a union of connected components of $X$.
\end{enumerate}

\label{lemma-characterize-limit}
Let $\mathcal{I}$ be a cofiltered category. Let $i \mapsto X_i$ be a diagram
of topological spaces over $\mathcal{I}$. Let $X$ be a topological
space such that
\begin{enumerate}
\item $X = \lim X_i$ as a set (denote $f_i$ the projection maps),
\item the sets $f_i^{-1}(U_i)$ for $i \in \Ob(\mathcal{I})$ and
$U_i \subset X_i$ open form a basis for the topology of $X$.
\end{enumerate}
Then $X$ is the limit of the $X_i$ as a topological space.

\label{lemma-normal-closure}
\begin{slogan}
Existence of normal closure of finite extensions of fields.
\end{slogan}
Let $E/F$ be a finite extension of fields. There exists a unique
smallest finite extension $K/E$ such that $K$ is normal over $F$.

\label{lemma-easy-ff}
Let $R$ be a ring.
Let $M$ be an $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is faithfully flat, and
\item $M$ is flat and for all $R$-module homomorphisms $\alpha : N \to N'$
we have $\alpha = 0$ if and only if $\alpha \otimes \text{id}_M = 0$.
\end{enumerate}

\label{lemma-glueing-near-closed-point-modules}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\mathcal{O}_S\text{-modules }\mathcal{F}\text{ of finite presentation}
\right\}
\longrightarrow
\left\{
(\mathcal{G}, \mathcal{H}, \alpha)
\right\}
$$
where on the right hand side we consider triples
consisting of a $\mathcal{O}_U$-module $\mathcal{G}$ of
finite presentation, a $\mathcal{O}_{\Spec(\mathcal{O}_{S, s})}$-module
$\mathcal{H}$ of finite presentation, and an isomorphism
$\alpha : \mathcal{G}|_V \to \mathcal{H}|_V$ of
$\mathcal{O}_V$-modules.

\label{lemma-separable-elements}
Let $E/k$ be a field extension. Then the elements of $E$ separable
over $k$ form a subextension of $E/k$.

\label{proposition-approximate}
Let $S$ be a quasi-compact and quasi-separated scheme.
There exist a directed set $I$
and an inverse system of schemes $(S_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $S_i$ is of finite type over $\mathbf{Z}$, and
\item $S = \lim_i S_i$.
\end{enumerate}

\label{lemma-composition-cartesian}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category over $\mathcal{C}$.
\begin{enumerate}
\item The composition of two strongly cartesian morphisms
is strongly cartesian.
\item Any isomorphism of $\mathcal{S}$ is strongly cartesian.
\item Any strongly cartesian morphism $\varphi$ such that $p(\varphi)$
is an isomorphism, is an isomorphism.
\end{enumerate}

\label{lemma-purely-inseparable-permanence}
Let $E/k$ and $F/E$ be purely inseparable extensions of fields. Then $F/k$
is a purely inseparable extension of fields.

\label{lemma-quasi-compact-closed-point}
Let $X$ be a topological space. Assume that
\begin{enumerate}
\item $X$ is nonempty,
\item $X$ is quasi-compact, and
\item $X$ is Kolmogorov.
\end{enumerate}
Then $X$ has a closed point.

\label{lemma-catenary}
Let $X$ be a topological space.
The following are equivalent:
\begin{enumerate}
\item $X$ is catenary,
\item $X$ has an open covering by catenary spaces.
\end{enumerate}
Moreover, in this case any locally closed subspace of $X$ is catenary.

\label{lemma-algebraic-finitely-generated}
\begin{slogan}
A finitely generated algebraic extension is finite.
\end{slogan}
Let $k$ be a field, and let $\alpha_1, \alpha_2, \ldots, \alpha_n$ be elements
of some extension field such that each $\alpha_i$ is algebraic over $k$. Then
the extension $k(\alpha_1, \ldots, \alpha_n)/k$ is finite.
That is, a finitely generated algebraic extension is finite.

\label{lemma-normal-case}
Let $E/F$ be a normal algebraic field extension. There exist subextensions
$E / E_{sep} /F$ and $E / E_{insep} / F$ such that
\begin{enumerate}
\item $F \subset E_{sep}$ is Galois and $E_{sep} \subset E$
is purely inseparable,
\item $F \subset E_{insep}$ is purely inseparable and $E_{insep} \subset E$
is Galois,
\item $E = E_{sep} \otimes_F E_{insep}$.
\end{enumerate}

\label{lemma-characterize-local-ring-map}
Let $\varphi : R \to S$ be a ring map. Assume $R$ and $S$ are local rings.
The following are equivalent:
\begin{enumerate}
\item $\varphi$ is a local ring map,
\item $\varphi(\mathfrak m_R) \subset \mathfrak m_S$,
\item $\varphi^{-1}(\mathfrak m_S) = \mathfrak m_R$, and
\item for any $x \in R$, if $\varphi(x)$ is invertible in $S$, then $x$
is invertible in $R$.
\end{enumerate}

\label{lemma-contained-in-radical}
Let $R$ be a ring with Jacobson radical $\text{rad}(R)$.
Let $I \subset R$ be an ideal. The following are
equivalent
\begin{enumerate}
\item $I \subset \text{rad}(R)$, and
\item every element of $1 + I$ is a unit in $R$.
\end{enumerate}
In this case every element of $R$ which maps to a unit of $R/I$ is a unit.

\label{proposition-affine}
\begin{slogan}
A scheme admitting a surjective integral map from an affine scheme is affine.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes. Assume $X$ is affine
and that $f$ is surjective and universally closed\footnote{An integral
morphism is universally closed, see
Morphisms, Lemma \ref{morphisms-lemma-integral-universally-closed}.}.
Then $S$ is affine.

\label{proposition-localize-twice-module}
View $S'^{-1}M$ as an $A$-module, then $S^{-1}(S'^{-1}M)$ is
isomorphic to $(SS')^{-1}M$.

\label{lemma-profinite-group}
Let $G$ be a topological group. The following are equivalent
\begin{enumerate}
\item $G$ as a topological space is profinite,
\item $G$ is a limit of a diagram of finite discrete topological groups,
\item $G$ is a cofiltered limit of finite discrete topological groups.
\end{enumerate}

\label{lemma-limit-from-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $X \to S$ be quasi-separated and of finite type.
Given $i \in I$ and a diagram
$$
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
S \ar[r] & S_i
}
}
$$
as in (\ref{equation-good-diagram}) for $i' \geq i$ let
$X_{i'}$ be the scheme theoretic image of $X \to S_{i'} \times_{S_i} W$.
Then $X = \lim_{i' \geq i} X_{i'}$.

\label{lemma-immersion-when-closed}
Let $f : Y \to X$ be an immersion of schemes. Then $f$ is a closed
immersion if and only if $f(Y) \subset X$ is a closed subset.

\label{lemma-glue-functors}
Let $F$ be a contravariant functor on the category of schemes
with values in the category of sets. Suppose that
\begin{enumerate}
\item $F$ satisfies the sheaf property for the Zariski topology,
\item there exists a set $I$ and a collection of subfunctors
$F_i \subset F$ such that
\begin{enumerate}
\item each $F_i$ is representable,
\item each $F_i \subset F$ is representable by open immersions, and
\item the collection $(F_i)_{i \in I}$ covers $F$.
\end{enumerate}
\end{enumerate}
Then $F$ is representable.

\label{lemma-ameliorate-morphism-fibred-categories}
Let $\mathcal{C}$ be a category. Let $F : \mathcal{X} \to \mathcal{Y}$
be a $1$-morphism of fibred categories over $\mathcal{C}$.
There exist $1$-morphisms of fibred categories over $\mathcal{C}$
$$
\xymatrix{
\mathcal{X} \ar@<1ex>[r]^u &
\mathcal{X}' \ar[r]^v \ar@<1ex>[l]^w & \mathcal{Y}
}
$$
such that $F = v \circ u$ and such that
\begin{enumerate}
\item $u : \mathcal{X} \to \mathcal{X}'$ is fully faithful,
\item $w$ is left adjoint to $u$, and
\item $v : \mathcal{X}' \to \mathcal{Y}$ is a fibred category.
\end{enumerate}

\label{lemma-constructible-stable-specialization-closed}
Let $R$ be a ring. Let $E \subset \Spec(R)$ be a constructible subset.
\begin{enumerate}
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E$ is stable under generalization, then $E$ is open.
\end{enumerate}

\label{lemma-2-category-fibred-sets}
\begin{slogan}
Categories fibred in sets are precisely presheaves.
\end{slogan}
Let $\mathcal{C}$ be a category.
The only $2$-morphisms between categories fibred in sets are identities.
In other words, the $2$-category of categories fibred in sets is a category.
Moreover, there is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{the category of presheaves}\\
\text{of sets over }\mathcal{C}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{the category of categories}\\
\text{fibred in sets over }\mathcal{C}
\end{matrix}
\right\}
$$
The functor from left to right is the construction
$F \to \mathcal{S}_F$ discussed in
Example \ref{example-presheaf}.
The functor from right to left assigns to $p : \mathcal{S} \to \mathcal{C}$
the presheaf of objects $U \mapsto \Ob(\mathcal{S}_U)$.

\label{lemma-essentially-finite-type-criterion-proper}
Let $S$ be a Nagata scheme (and in particular locally Noetherian).
Let $f : X \to Y$ be a quasi-compact morphism of schemes locally
of finite type over $S$. The following are equivalent
\begin{enumerate}
\item $f$ proper,
\item for any commutative diagram
$$
\xymatrix{
U \ar[r] \ar[d] & X \ar[d]^f \\
C \ar[r] \ar@{..>}[ru] & Y
}
$$
of schemes over $S$ such that
\begin{enumerate}
\item $C$ is a normal integral scheme of finite type over $S$,
\item $U = C \setminus \{c\}$ for some closed point $c \in C$,
\item $A = \mathcal{O}_{C, c}$ has dimension $1$\footnote{It follows
that $A$ is a discrete valuation ring, see
Algebra, Lemma \ref{algebra-lemma-characterize-dvr}.
Moreover, $c$ maps to a finite type point $s \in S$ and
$A$ is essentially of finite type over $\mathcal{O}_{S, s}$.}
\end{enumerate}
then in the commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d]^f \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $K = \text{Frac}(A)$ there exists exactly one dotted arrow\footnote{By
Lemma \ref{lemma-morphism-glueing-near-closed-point} this is
equivalent to asking for the existence and uniqueness of the dotted arrow
making the first commutative diagram commute.}
making the diagram commute.
\end{enumerate}

\label{lemma-quasi-compact-open-immersion-constructible-image}
Let $U \subset X$ be a retrocompact open. Let $E \subset U$.
If $E$ is constructible in $U$, then $E$ is constructible in $X$.

\label{lemma-standard-open}
Let $R$ be a ring. Let $f \in R$.
\begin{enumerate}
\item If $g\in R$ and $D(g) \subset D(f)$, then
\begin{enumerate}
\item $f$ is invertible in $R_g$,
\item $g^e = af$ for some $e \geq 1$ and $a \in R$,
\item there is a canonical ring map $R_f \to R_g$, and
\item there is a canonical $R_f$-module map
$M_f \to M_g$ for any $R$-module $M$.
\end{enumerate}
\item Any open covering of $D(f)$ can be refined to a finite
open covering of the form $D(f) = \bigcup_{i = 1}^n D(g_i)$.
\item If $g_1, \ldots, g_n \in R$, then $D(f) \subset \bigcup D(g_i)$
if and only if $g_1, \ldots, g_n$ generate the unit ideal in $R_f$.
\end{enumerate}

\label{lemma-localize-quotient-modules}
Localization respects quotients, i.e. if $N$ is a submodule of
$M$, then $S^{-1}(M/N)\simeq (S^{-1}M)/(S^{-1}N)$.

\label{lemma-present-sym-wedge}
Let $R$ be a ring.
Let $M$ be an $R$-module.
Let $x_i$, $i \in I$ be a given system of generators of
$M$ as an $R$-module. Let $n \geq 2$.
There exists a canonical exact sequence
$$
\bigoplus_{1 \leq j_1 < j_2 \leq n}
\bigoplus_{i_1, i_2 \in I}
\text{T}^{n - 2}(M)
\oplus
\bigoplus_{1 \leq j_1 < j_2 \leq n}
\bigoplus_{i \in I}
\text{T}^{n - 2}(M)
\to
\text{T}^n(M)
\to
\wedge^n(M)
\to
0
$$
where the pure tensor $m_1 \otimes \ldots \otimes m_{n - 2}$ in the first
summand maps to
\begin{align*}
\underbrace{
m_1 \otimes \ldots \otimes x_{i_1} \otimes \ldots
\otimes x_{i_2} \otimes \ldots \otimes m_{n - 2}
}_{\text{with } x_{i_1} \text{ and } x_{i_2}
\text{ occupying slots } j_1 \text{ and } j_2
\text{ in the tensor}} \\
+
\underbrace{
m_1 \otimes \ldots \otimes x_{i_2} \otimes \ldots
\otimes x_{i_1} \otimes \ldots \otimes m_{n - 2}
}_{\text{with } x_{i_2} \text{ and } x_{i_1}
\text{ occupying slots } j_1 \text{ and } j_2
\text{ in the tensor}}
\end{align*}
and $m_1 \otimes \ldots \otimes m_{n - 2}$ in the second
summand maps to
$$
\underbrace{
m_1 \otimes \ldots \otimes x_i \otimes \ldots
\otimes x_i \otimes \ldots \otimes m_{n - 2}
}_{\text{with } x_{i} \text{ and } x_{i}
\text{ occupying slots } j_1 \text{ and } j_2
\text{ in the tensor}}
$$
There is also a canonical exact sequence
$$
\bigoplus_{1 \leq j_1 < j_2 \leq n}
\bigoplus_{i_1, i_2 \in I}
\text{T}^{n - 2}(M)
\to
\text{T}^n(M)
\to
\text{Sym}^n(M)
\to
0
$$
where the pure tensor $m_1 \otimes \ldots \otimes m_{n - 2}$ maps to
\begin{align*}
\underbrace{
m_1 \otimes \ldots \otimes x_{i_1} \otimes \ldots
\otimes x_{i_2} \otimes \ldots \otimes m_{n - 2}
}_{\text{with } x_{i_1} \text{ and } x_{i_2}
\text{ occupying slots } j_1 \text{ and } j_2
\text{ in the tensor}} \\
-
\underbrace{
m_1 \otimes \ldots \otimes x_{i_2} \otimes \ldots
\otimes x_{i_1} \otimes \ldots \otimes m_{n - 2}
}_{\text{with } x_{i_2} \text{ and } x_{i_1}
\text{ occupying slots } j_1 \text{ and } j_2
\text{ in the tensor}}
\end{align*}

\label{lemma-constructible}
The collection of constructible sets is closed under
finite intersections, finite unions and complements.

\label{lemma-describe-limits}
Let $\mathcal{I}$ be a cofiltered category. Let $i \mapsto X_i$ be a diagram
of topological spaces over $\mathcal{I}$. Let $X = \lim X_i$ be the limit
with projection maps $f_i : X \to X_i$.
\begin{enumerate}
\item Any open of $X$ is of the form $\bigcup_{j \in J} f_j^{-1}(U_j)$
for some subset $J \subset I$ and opens $U_j \subset X_j$.
\item Any quasi-compact open of $X$ is of the form
$f_i^{-1}(U_i)$ for some $i$ and some $U_i \subset X_i$ open.
\end{enumerate}

\label{lemma-characterize-constructible-Noetherian}
Let $X$ be a Noetherian topological space.
Let $E \subset X$ be a subset.
The following are equivalent:
\begin{enumerate}
\item $E$ is constructible in $X$, and
\item for every irreducible closed $Z \subset X$ the intersection
$E \cap Z$ either contains a nonempty open of $Z$ or is not dense in $Z$.
\end{enumerate}

\label{lemma-immersions-monomorphisms}
An immersion of schemes is a monomorphism.
In particular, any immersion is separated.

\label{lemma-quotient-field-map}
Notation and assumptions as in Lemma \ref{lemma-quotient}.
If $\Spec(k) \to U/G$ is a morphism, then there exist
\begin{enumerate}
\item a finite Galois extension $k'/k$,
\item a finite subgroup $H \subset G$,
\item an isomorphism $H \to \text{Gal}(k'/k)$, and
\item an $H$-equivariant morphism $\Spec(k') \to U$.
\end{enumerate}
Conversely, such data determine a morphism $\Spec(k) \to U/G$.

\label{lemma-domain-image-dense-set-points-generic-point}
Let $R$ be a domain. Let $\varphi : R \to S$ be a ring map.
The following are equivalent:
\begin{enumerate}
\item The ring map $R \to S$ is injective.
\item The image $\Spec(S) \to \Spec(R)$
contains a dense set of points.
\item There exists a prime ideal $\mathfrak q \subset S$
whose inverse image in $R$ is $(0)$.
\end{enumerate}

\label{lemma-connected-components}
Let $X$ be a topological space.
\begin{enumerate}
\item If $T \subset X$ is connected, then so is its closure.
\item Any connected component of $X$ is closed (but not necessarily open).
\item Every connected subset of $X$ is contained in a unique connected
component of $X$.
\item Every point of $X$ is contained in a unique connected component, in other
words, $X$ is the disjoint union of its connected components.
\end{enumerate}

\label{lemma-affine-separated}
An affine scheme is separated. A morphism from an affine scheme
to another scheme is separated.

\label{lemma-points-specialize}
\begin{slogan}
Specializations are witnessed by valuation rings.
\end{slogan}
Let $S$ be a scheme. Let $s' \leadsto s$ be a specialization of points of $S$.
Then
\begin{enumerate}
\item there exists a valuation ring $A$ and a morphism
$f : \Spec(A) \to S$ such that the generic point $\eta$ of
$\Spec(A)$ maps to $s'$ and the special point maps to $s$, and
\item given a field extension $K/\kappa(s')$
we may arrange it so that the extension
$\kappa(\eta)/\kappa(s')$ induced by $f$
is isomorphic to the given extension.
\end{enumerate}

\label{lemma-topological-ring-colimits}
The category of topological rings has colimits and colimits commute
with the forgetful functor to the category of rings.

\label{lemma-going-up-closed}
Let $R \to S$ be a ring map. The following are equivalent:
\begin{enumerate}
\item Going up holds for $R \to S$, and
\item the map $\Spec(S) \to \Spec(R)$ is closed.
\end{enumerate}

\label{lemma-pid-jacobson}
The ring $\mathbf{Z}$ is a Jacobson ring.
More generally, let $R$ be a ring such that
\begin{enumerate}
\item $R$ is a domain,
\item $R$ is Noetherian,
\item any nonzero prime ideal is a maximal ideal, and
\item $R$ has infinitely many maximal ideals.
\end{enumerate}
Then $R$ is a Jacobson ring.

\label{proposition-universal-property-localization}
Let $f : A \to B$ be a ring map that sends every element in $S$ to a unit
of $B$. Then there is a unique homomorphism $g : S^{-1}A \to B$ such
that the following diagram commutes.
$$
\xymatrix{
A \ar[rr]^{f} \ar[dr] & & B \\
& S^{-1}A \ar[ur]_g
}
$$

\label{lemma-locally-Noetherian-locally-connected}
Let $X$ be a locally Noetherian topological space.
Then $X$ is locally connected.

\label{lemma-closed-points-quasi-compact}
Let $X$ be a quasi-compact Kolmogorov space. Then the set $X_0$ of
closed points of $X$ is quasi-compact.

\label{lemma-stable-specialization}
Let $T \subset X$ be a subset of a topological space $X$.
The following are equivalent
\begin{enumerate}
\item $T$ is stable under specialization, and
\item $T$ is a (directed) union of closed subsets of $X$.
\end{enumerate}

\label{lemma-infinite-product}
\begin{slogan}
Infinite products of affine schemes exist and are affine.
\end{slogan}
Let $S$ be a scheme. Let $I$ be a set and for each $i \in I$
let $f_i : T_i \to S$ be an affine morphism. Then the
product $T = \prod T_i$ exists in the category of schemes
over $S$. In fact, we have
$$
T = \lim_{\{i_1, \ldots, i_n\} \subset I}
T_{i_1} \times_S \ldots \times_S T_{i_n}
$$
and the projection morphisms $T \to T_{i_1} \times_S \ldots \times_S T_{i_n}$
are affine.

\label{lemma-closed-map}
\begin{slogan}
A map from a compact space to a Hausdorff space is universally closed.
\end{slogan}
Let $f : X \to Y$ be a continuous map of topological spaces.
If $X$ is quasi-compact and $Y$ is Hausdorff, then $f$ is
universally closed.

\label{lemma-descend-immersion}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an immersion, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is an immersion for some $i \geq 0$.

\label{lemma-what-is-in-it-G-sets}
Let $\alpha$ be an ordinal as in Lemma \ref{lemma-sets-with-group-action}
above. The category $G\textit{-Sets}_\alpha$ satisfies the following
properties:
\begin{enumerate}
\item The $G$-set ${}_GG$ is an object of $G\textit{-Sets}_\alpha$.
\item (Co)Products, fibre products, and pushouts
exist in $G\textit{-Sets}_\alpha$
and are the same as their counterparts in $G\textit{-Sets}$.
\item Given an object $U$ of $G\textit{-Sets}_\alpha$,
any $G$-stable subset $O \subset U$  is isomorphic to an object
of $G\textit{-Sets}_\alpha$.
\end{enumerate}

\label{lemma-finite-transitive}
Suppose that $R \to S$ and $S \to T$ are finite ring maps.
Then $R \to T$ is finite.

\label{lemma-associativity-2-fibre-product}
Let
$$
\xymatrix{
\mathcal{A} \ar[rd] & & \mathcal{C} \ar[ld] \ar[rd] & & \mathcal{E} \ar[ld] \\
& \mathcal{B} & & \mathcal{D}
}
$$
be a diagram of categories and functors.
Then there is a canonical isomorphism
$$
(\mathcal{A} \times_\mathcal{B} \mathcal{C}) \times_\mathcal{D} \mathcal{E}
\cong
\mathcal{A} \times_\mathcal{B} (\mathcal{C} \times_\mathcal{D} \mathcal{E})
$$
of categories.

\label{lemma-nowhere-dense}
Let $X$ be a topological space. The union of a finite number of nowhere
dense sets is a nowhere dense set.

\label{lemma-left-localization}
Let $\mathcal{C}$ be a category and let $S$ be a left multiplicative
system.
\begin{enumerate}
\item The relation on pairs defined above is an equivalence relation.
\item The composition rule given above is well defined on equivalence
classes.
\item Composition is associative (and the identity morphisms satisfy
the identity axioms), and hence $S^{-1}\mathcal{C}$ is a category.
\end{enumerate}

\label{lemma-eventually-relative-dimension}
Assumptions and notation as in Situation \ref{situation-descent-property}.
Let $d \geq 0$. If
\begin{enumerate}
\item $f$ has relative dimension $\leq d$
(Morphisms, Definition \ref{morphisms-definition-relative-dimension-d}), and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i$ such that $f_i$ has relative dimension $\leq d$.

\label{lemma-descend-separated-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If $f$ is separated, then $f_i$ is separated for some $i \geq 0$.

\label{lemma-generating-finitely-generated-separable-field-extensions}
Let $K/k$ be a separably generated, and finitely generated
field extension.
Set $r = \text{trdeg}_k(K)$. Then there exist elements
$x_1, \ldots, x_{r + 1}$ of $K$ such that
\begin{enumerate}
\item $x_1, \ldots, x_r$ is a transcendence basis of $K$ over $k$,
\item $K = k(x_1, \ldots, x_{r + 1})$, and
\item $x_{r + 1}$ is separable over $k(x_1, \ldots, x_r)$.
\end{enumerate}

\label{lemma-relatively-prime-polynomials}
Two polynomials in $k[x]$ are relatively prime precisely when they
have no common roots in an algebraic closure $\overline{k}$ of $k$.

\label{lemma-separable-permanence}
Let $E/k$ and $F/E$ be separable algebraic extensions of fields. Then $F/k$
is a separable extension of fields.

\label{lemma-finite-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
If $K$ is finite over $F$, then $K$ is finite over $E$.

\label{lemma-ff-rings}
Let $R \to S$ be a flat ring map.
The following are equivalent:
\begin{enumerate}
\item $R \to S$ is faithfully flat,
\item the induced map on $\Spec$ is surjective, and
\item any closed point $x \in \Spec(R)$ is
in the image of the map $\Spec(S) \to \Spec(R)$.
\end{enumerate}

\label{lemma-flat-eq}
A module $M$ over $R$ is flat if and only if
every relation in $M$ is trivial.

\label{lemma-locally-quasi-compact-Hausdorff}
A Hausdorff space is locally quasi-compact if and only if every point
has a quasi-compact neighbourhood.

\label{lemma-push-outs-coequalizers-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Connected finite colimits exist in $\mathcal{C}$.
\item Coequalizers and pushouts exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-essentially-finite-type-criterion-separation}
Let $S$ be a Nagata scheme (and in particular locally Noetherian).
Let $f : X \to Y$ be a morphism of schemes locally of finite type over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ separated,
\item for any commutative diagram
$$
\xymatrix{
U \ar[r] \ar[d] & X \ar[d]^f \\
C \ar[r] \ar@{..>}[ru] & Y
}
$$
of schemes over $S$ such that
\begin{enumerate}
\item $C$ is a normal integral scheme of finite type over $S$,
\item $U = C \setminus \{c\}$ for some closed point $c \in C$,
\item $A = \mathcal{O}_{C, c}$ has dimension $1$\footnote{It follows
that $A$ is a discrete valuation ring, see
Algebra, Lemma \ref{algebra-lemma-characterize-dvr}.
Moreover, $c$ maps to a finite type point $s \in S$ and
$A$ is essentially of finite type over $\mathcal{O}_{S, s}$.}
\end{enumerate}
then in the commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d]^f \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $K = \text{Frac}(A)$ there exists at most one dotted arrow\footnote{By
Lemma \ref{lemma-morphism-glueing-near-closed-point} this is
equivalent to asking there to be at most one dotted arrow
making the first commutative diagram commute.}
making the diagram commute.
\end{enumerate}

\label{lemma-compose-counits}
Let $\mathcal{A}$, $\mathcal{B}$, and $\mathcal{C}$ be categories.
Let $v : \mathcal{A} \to \mathcal{B}$ and
$v' : \mathcal{B} \to \mathcal{C}$ be functors
with left adjoints $u$ and $u'$ respectively. Then
\begin{enumerate}
\item The functor $v'' = v' \circ v$ has a left adjoint equal to
$u'' = u \circ u'$.
\item Given $X$ in $\mathcal{A}$ we have
\begin{equation}
\label{equation-compose-counits}
\epsilon_X^v \circ u(\epsilon^{v'}_{v(X)}) = \epsilon^{v''}_X :
u''(v''(X)) \to X
\end{equation}
Where $\epsilon$ is the counit of the adjunctions.
\end{enumerate}

\label{lemma-flip-tensor-product}
Let $M, N, P$ be $R$-modules, then the bilinear maps
\begin{align*}
(x, y) & \mapsto y \otimes x\\
(x + y, z) & \mapsto x \otimes z + y \otimes z\\
(r, x) & \mapsto rx
\end{align*}
induce unique isomorphisms
\begin{align*}
M \otimes_R N & \to N \otimes_R M, \\
(M\oplus N)\otimes_R P & \to (M \otimes_R P)\oplus(N \otimes_R P),  \\
R \otimes_R M & \to M
\end{align*}

\label{lemma-unique-prime-over-localize-below}
Let $R \to S$ be a ring map.
Let $\mathfrak p \subset R$ be a prime.
Assume that
\begin{enumerate}
\item there exists a unique prime $\mathfrak q \subset S$ lying over
$\mathfrak p$, and
\item either
\begin{enumerate}
\item going up holds for $R \to S$, or
\item going down holds for $R \to S$ and there is at most one prime
of $S$ above every prime of $R$.
\end{enumerate}
\end{enumerate}
Then $S_{\mathfrak p} = S_{\mathfrak q}$.

\label{lemma-descend-flat-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is flat,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is flat for some $i \geq 0$.

\label{lemma-locally-nilpotent}
Let $R \to R'$ be a ring map and let $I \subset R$ be a locally nilpotent
ideal. Then $IR'$ is a locally nilpotent ideal of $R'$.

\label{lemma-descend-open-immersion}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an open immersion, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is an open immersion for some $i \geq 0$.

\label{lemma-characterize-finitely-presented-module-hom}
Let $R$ be a ring. Let $N$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $N$ is a finitely presented $R$-module,
\item for any filtered colimit $M = \colim M_i$ of $R$-modules the map
$\colim \Hom_R(N, M_i) \to \Hom_R(N, M)$ is bijective.
\end{enumerate}

\label{lemma-morphism-glueing-near-closed-point}
Let $S$ be a scheme. Let $X$ and $Y$ be schemes over $S$.
Assume $Y$ is locally of finite presentation over $S$.
Let $x \in X$ be a closed point such that
$U = X \setminus \{x\} \to X$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}) \setminus \{x\}$ there is
a bijection
$$
\left\{
\begin{matrix}
\text{morphisms }X \to Y\text{ over }S
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
(a, b)\text{ where }
a : U \to Y\text{ and }b : \Spec(\mathcal{O}_{X, x}) \to Y\\
\text{ are morphisms over }S
\text{ which agree over }V
\end{matrix}
\right\}
$$

\label{lemma-fibre-topological}
Let $f : X \to S$ be a morphism of schemes.
Consider the diagrams
$$
\vcenter{
\xymatrix{
X_s \ar[r] \ar[d] & X \ar[d] \\
\Spec(\kappa(s)) \ar[r] & S
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Spec(\mathcal{O}_{S, s}) \times_S X \ar[r] \ar[d] & X \ar[d] \\
\Spec(\mathcal{O}_{S, s}) \ar[r] & S
}
}
$$
In both cases these diagrams induce fibre squares of topological
spaces and in particular, the top horizontal arrow is a homeomorphism
onto its image.

\label{lemma-injective-points}
Let $j : X \to Y$ be a morphism of schemes.
If $j$ is injective on points, then $j$ is separated.

\label{lemma-modifications}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ the base change functor
$$
\left\{
\begin{matrix}
f : X \to S\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{S, s})\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

\label{lemma-descend-syntomic}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is syntomic, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is syntomic.

\label{lemma-colon}
Let $R$ be a ring. For a principal ideal $J \subset R$, and for any ideal
$I \subset J$ we have $I = J (I : J)$.

\label{lemma-almost-finite-limits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Nonempty finite limits exist in $\mathcal{C}$.
\item Products of pairs and equalizers exist in $\mathcal{C}$.
\item Products of pairs and fibre products exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-fibre-product-closed}
Let $X \to Z$ and $Y \to Z$ be continuous maps of topological spaces.
If $Z$ is Hausdorff, then $X \times_Z Y$ is closed in $X \times Y$.

\label{lemma-representable-over-representable}
Let $\mathcal{C}$ be a category.
Let $a : F \to G$ be a morphism of contravariant functors
from $\mathcal{C}$ to $\textit{Sets}$. If $a$ is representable,
and $G$ is a representable functor, then $F$ is representable.

\label{lemma-invertible}
Let $\mathcal{C}$ be a monoidal category. Let $X$ be an object of
$\mathcal{C}$. The following are equivalent
\begin{enumerate}
\item the functor $L : Y \mapsto X \otimes Y$ is an equivalence,
\item the functor $R : Y \mapsto Y \otimes X$ is an equivalence,
\item there exists an object $X'$ such that
$X \otimes X' \cong X' \otimes X \cong \mathbf{1}$.
\end{enumerate}

\label{lemma-Hausdorff}
Let $X$ be a topological space. The following are equivalent:
\begin{enumerate}
\item $X$ is Hausdorff,
\item the diagonal $\Delta(X) \subset X \times X$ is closed.
\end{enumerate}

\label{lemma-quotient-finite-separated}
Notation and assumptions as in Lemma \ref{lemma-quotient}.
Assume $G$ is finite. Then
\begin{enumerate}
\item if $U \to S$ is quasi-separated, then $U/G$ is quasi-separated
over $S$, and
\item if $U \to S$ is separated, then $U/G$ is separated over $S$.
\end{enumerate}

\label{lemma-reduced}
A scheme $X$ is reduced if and only if $\mathcal{O}_X(U)$
is a reduced ring for all $U \subset X$ open.

\label{lemma-colimits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Finite colimits exist in $\mathcal{C}$.
\item Finite coproducts and coequalizers exist in $\mathcal{C}$.
\item The category has an initial object and pushouts exist.
\end{enumerate}

\label{lemma-affines-glued-in-closed-affine}
Let $X$ be a scheme which is set theoretically the union of
finitely many affine closed subschemes. Then $X$ is affine.

\label{lemma-glueing-near-point}
Let $S$ be a scheme. Let $U \subset S$ be a retrocompact open.
Let $s \in S$ be a point in the complement of $U$. With
$V = \Spec(\mathcal{O}_{S, s}) \cap U$ there is
an equivalence of categories
$$
\colim_{s \in U' \supset U\text{ open}}
\left\{
\vcenter{
\xymatrix{
X \ar[d] \\
U'
}
}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the left hand side the vertical arrow is of finite
presentation and on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

\label{lemma-algebraic-elements}
Let $E/k$ be a field extension. Then the elements of $E$ algebraic over $k$
form a subextension of $E/k$.

\label{lemma-separable-trace-pairing}
Let $L/K$ be a finite extension of fields. The following are equivalent:
\begin{enumerate}
\item $L/K$ is separable,
\item $\text{Trace}_{L/K}$ is not identically zero, and
\item the trace pairing $Q_{L/K}$ is nondegenerate.
\end{enumerate}

\label{lemma-characterize-closed-immersions}
Let $f : X \to Y$ be a morphism of schemes.
Suppose that
\begin{enumerate}
\item $f$ induces a homeomorphism of $X$ with a
closed subset of $Y$, and
\item $f^\sharp : \mathcal{O}_Y \to f_*\mathcal{O}_X$
is surjective.
\end{enumerate}
Then $f$ is a closed immersion of schemes.

\label{lemma-Noetherian-irreducible-components}
\begin{slogan}
A Noetherian affine scheme has finitely many generic points.
\end{slogan}
If $R$ is a Noetherian ring then $\Spec(R)$
has finitely many irreducible components. In other words
$R$ has finitely many minimal primes.

\label{lemma-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $X \to S$ be quasi-separated and of finite type.
Then there exists an $i \in I$ and a diagram
\begin{equation}
\label{equation-good-diagram}
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
S \ar[r] & S_i
}
}
\end{equation}
such that $W \to S_i$ is of finite type and such that
the induced morphism $X \to S \times_{S_i} W$ is a closed
immersion.

\label{lemma-specializations-lift}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item If $f$ is universally closed then specializations lift
along any base change of $f$, see
Topology, Definition \ref{topology-definition-lift-specializations}.
\item If $f$ is quasi-compact and specializations lift
along any base change of $f$, then $f$ is universally closed.
\end{enumerate}

\label{lemma-representable-over-space}
\begin{slogan}
A functor that admits a representable morphism to an algebraic space is
an algebraic space.
\end{slogan}
Let $S$ be a scheme contained in $\Sch_{fppf}$.
Let $F$ be an algebraic space over $S$.
Let $G \to F$ be a representable transformation of functors.
Then $G$ is an algebraic space.

\label{lemma-image-quasi-compact-closed}
Let $f : X \to S$ be a quasi-compact morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f(X) \subset S$ is closed, and
\item $f(X) \subset S$ is stable under specialization.
\end{enumerate}

\label{lemma-base-change-Jacobson}
Let $k$ be a field. Let $S$ be a $k$-algebra.
For any field extension $K/k$ whose cardinality is larger
than the cardinality of $S$ we have
\begin{enumerate}
\item for every maximal ideal $\mathfrak m$ of $S_K$ the field
$\kappa(\mathfrak m)$ is algebraic over $K$, and
\item $S_K$ is a Jacobson ring.
\end{enumerate}

\label{lemma-Noetherian-power-series}
If $R$ is a Noetherian ring, then so is the formal power
series ring $R[[x_1, \ldots, x_n]]$.

\label{lemma-characterize-open-Noetherian}
Let $X$ be a Noetherian topological space.
Let $E \subset X$ be a subset.
The following are equivalent:
\begin{enumerate}
\item $E$ is open in $X$, and
\item for every irreducible closed subset $Y$ of $X$
the intersection $E \cap Y$ is either empty or
contains a nonempty open of $Y$.
\end{enumerate}

\label{lemma-adjoint-fully-faithful}
Let $u$ be a left adjoint to $v$ as in Definition \ref{definition-adjoint}.
Then
\begin{enumerate}
\item $u$ is fully faithful $\Leftrightarrow$ $\text{id} \cong v \circ u$
$\Leftrightarrow$ $\eta : \text{id} \to v \circ u$ is an isomorphism,
\item $v$ is fully faithful $\Leftrightarrow$
$u \circ v \cong \text{id}$ $\Leftrightarrow$
$\epsilon : u \circ v \to \text{id}$ is an isomorphism.
\end{enumerate}

\label{lemma-tensor-finiteness}
Let $R$ be a ring. Let $M$ and $N$ be $R$-modules.
\begin{enumerate}
\item If $N$ and $M$ are finite, then so is $M \otimes_R N$.
\item If $N$ and $M$ are finitely presented, then so is $M \otimes_R N$.
\end{enumerate}

\label{lemma-isomorphism-locally-ringed}
\begin{slogan}
An isomorphism of ringed spaces between locally ringed spaces is an
isomorphism of locally ringed spaces.
\end{slogan}
Let $X$, $Y$ be locally ringed spaces.
If $f : X \to Y$ is an isomorphism of
ringed spaces, then $f$ is an isomorphism
of locally ringed spaces.

\label{lemma-separable-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is separable over $F$, then $\alpha$ is separable
over $E$.
\item if $K$ is separable over $F$, then $K$ is separable over $E$.
\end{enumerate}

\label{lemma-Noetherian-finite-type-is-finite-presentation}
Let $R$ be a Noetherian ring.
\begin{enumerate}
\item Any finite $R$-module is of finite presentation.
\item Any submodule of a finite $R$-module is finite.
\item Any finite type $R$-algebra is of finite presentation over $R$.
\end{enumerate}

\label{lemma-integral-over-field}
Let $k$ be a field. Let $S$ be a $k$-algebra over $k$.
\begin{enumerate}
\item If $S$ is a domain and finite dimensional over $k$,
then $S$ is a field.
\item If $S$ is integral over $k$ and a domain,
then $S$ is a field.
\item If $S$ is integral over $k$ then every prime of
$S$ is a maximal ideal (see
Lemma \ref{lemma-ring-with-only-minimal-primes}
for more consequences).
\end{enumerate}

\label{lemma-base-change-integral}
\begin{slogan}
Integrality and finiteness are preserved under base change.
\end{slogan}
Let $R \to S$ and $R \to R'$ be ring maps.
Set $S' = R' \otimes_R S$.
\begin{enumerate}
\item If $R \to S$ is integral so is $R' \to S'$.
\item If $R \to S$ is finite so is $R' \to S'$.
\end{enumerate}

\label{lemma-base-change-separated}
Let $f : X \to Y$ and $Y' \to Y$ be continuous maps of topological spaces.
If $f$ is separated, then $f' : Y' \times_Y X \to Y'$ is separated.

\label{lemma-support-sheaf-rings-closed}
Let $X$ be a topological space.
The support of a sheaf of rings is closed.

\label{lemma-valuative-criterion-separatedness}
\begin{reference}
\cite[II Proposition 7.2.3]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism.
Assume
\begin{enumerate}
\item the morphism $f$ is quasi-separated, and
\item the morphism $f$ satisfies the uniqueness
part of the valuative criterion.
\end{enumerate}
Then $f$ is separated.

\label{lemma-separable-degree}
Let $K/F$ be a finite extension. Let $\overline{F}$ be an algebraic
closure of $F$. Then $[K : F]_s = |\Mor_F(K, \overline{F})|$.

\label{lemma-Noetherian-permanence}
\begin{slogan}
Noetherian property is stable by passage to finite type extension
and localization.
\end{slogan}
Any finitely generated ring over a Noetherian ring
is Noetherian. Any localization of a Noetherian ring
is Noetherian.

\label{lemma-descend-monomorphism}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a monomorphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is a monomorphism for some $i \geq 0$.

\label{lemma-flat-intersect-ideals}
Let $R$ be a ring. Let $I, J \subset R$ be ideals. Let $M$ be a flat
$R$-module. Then $IM \cap JM = (I \cap J)M$.

\label{lemma-transformation-between-functors-and-adjoints}
Let $u_1, u_2 : \mathcal{C} \to \mathcal{D}$ be functors with right
adjoints $v_1, v_2 : \mathcal{D} \to \mathcal{C}$. Let $\beta : u_2 \to u_1$
be a transformation of functors. Let $\beta^\vee : v_1 \to v_2$ be
the corresponding transformation of adjoint functors. Then
$$
\xymatrix{
u_2 \circ v_1 \ar[r]_\beta \ar[d]_{\beta^\vee} &
u_1 \circ v_1 \ar[d] \\
u_2 \circ v_2 \ar[r] & \text{id}
}
$$
is commutative where the unlabeled arrows are the counit transformations.

\label{lemma-descend-isomorphism}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an isomorphism, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is an isomorphism for some $i \geq 0$.

\label{lemma-subalgebra-algebraic-extension-field}
Let $E/F$ be a finite or more generally an algebraic extension of fields.
Any subring $F \subset R \subset E$ is a field.

\label{lemma-eventually-separated}
Let $S$ be a scheme. Let $X = \lim X_i$ be a directed
limit of schemes over $S$ with affine transition morphisms.
Assume
\begin{enumerate}
\item $S$ quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to S$ separated.
\end{enumerate}
Then $X_i \to S$ is separated for all $i$ large enough.

\label{lemma-locally-connected}
Let $X$ be a topological space. If $X$ is locally connected, then
\begin{enumerate}
\item any open subset of $X$ is locally connected, and
\item the connected components of $X$ are open.
\end{enumerate}
So also the connected components of open subsets of $X$ are open.
In particular, every point has a fundamental system of open connected
neighbourhoods.

\label{lemma-lift-specializations-images}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If specializations lift along $f$, and if $T \subset X$
is stable under specialization, then $f(T) \subset Y$ is
stable under specialization.
\item If generalizations lift along $f$, and if $T \subset X$
is stable under generalization, then $f(T) \subset Y$ is
stable under generalization.
\end{enumerate}

\label{lemma-relative-approximation}
Let $f : X \to S$ be a morphism of schemes. Assume that
\begin{enumerate}
\item $X$ is quasi-compact and quasi-separated, and
\item $S$ is quasi-separated.
\end{enumerate}
Then $X = \lim X_i$ is a limit of a directed system of schemes
$X_i$ of finite presentation over $S$ with affine transition morphisms
over $S$.

\label{lemma-module-quotient-flat}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item Any sheaf of $\mathcal{O}_X$-modules is a quotient of
a direct sum $\bigoplus j_{U_i!}\mathcal{O}_{U_i}$.
\item Any $\mathcal{O}_X$-module is a quotient of
a flat $\mathcal{O}_X$-module.
\end{enumerate}

\label{lemma-characterize-reduced-ring-normal}
Let $R$ be a ring. Assume $R$ is reduced and has finitely many
minimal primes. Then the following are equivalent:
\begin{enumerate}
\item $R$ is a normal ring,
\item $R$ is integrally closed in its total ring of fractions, and
\item $R$ is a finite product of normal domains.
\end{enumerate}

\label{lemma-obvious-Noetherian}
Any finite type algebra over a field is Noetherian.
Any finite type algebra over $\mathbf{Z}$ is Noetherian.

\label{lemma-separable-first-normal}
Let $E/F$ be a normal algebraic field extension. Then the subextension
$E/E_{sep}/F$ of Lemma \ref{lemma-separable-first} is normal.

\label{lemma-diagonal-1}
Let
$$
\xymatrix{
\mathcal{C}_3 \ar[r] \ar[d] & \mathcal{S} \ar[d]^\Delta \\
\mathcal{C}_1 \times \mathcal{C}_2 \ar[r]^{G_1 \times G_2} &
\mathcal{S} \times \mathcal{S}
}
$$
be a $2$-fibre product of categories.
Then there is a canonical isomorphism
$\mathcal{C}_3 \cong
\mathcal{C}_1 \times_{G_1, \mathcal{S}, G_2} \mathcal{C}_2$.

\label{lemma-field-maps-injective}
If $F$ is a field and $R$ is a nonzero ring, then any ring homomorphism
$\varphi : F \to R$ is injective.

\label{lemma-descend-quasi-finite}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a quasi-finite morphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is quasi-finite.

\label{lemma-finite-limits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Finite limits exist in $\mathcal{C}$.
\item Finite products and equalizers exist.
\item The category has a final object and fibre products exist.
\end{enumerate}

\label{lemma-flatness-descends-more-general}
Let $R$ be a ring. Let $S \to S'$ be a flat map of $R$-algebras.
Let $M$ be a module over $S$, and set $M' = S' \otimes_S M$.
\begin{enumerate}
\item If $M$ is flat over $R$, then $M'$ is flat over $R$.
\item If $S \to S'$ is faithfully flat, then $M$ is flat
over $R$ if and only if $M'$ is flat over $R$.
\end{enumerate}

\label{lemma-generic-point-in-constructible}
Let $X$ be a topological space. Suppose that
$Z \subset X$ is irreducible. Let $E \subset X$
be a finite union of locally closed subsets (e.g.\ $E$
is constructible). The following are equivalent
\begin{enumerate}
\item The intersection $E \cap Z$ contains an open
dense subset of $Z$.
\item The intersection $E \cap Z$ is dense in $Z$.
\end{enumerate}
If $Z$ has a generic point $\xi$, then this is
also equivalent to
\begin{enumerate}
\item[(3)] We have $\xi \in E$.
\end{enumerate}

\label{lemma-glue-schemes}
\begin{slogan}
Schemes can be glued to give new schemes.
\end{slogan}
In Lemma \ref{lemma-glue} above, assume that all
$X_i$ are schemes. Then the resulting locally ringed
space $X$ is a scheme.

\label{lemma-stalk-pullback-modules}
Let $(f, f^\sharp) : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$
be a morphism of ringed spaces.
Let $\mathcal{G}$ be a sheaf of $\mathcal{O}_Y$-modules.
Let $x \in X$. Then
$$
(f^*\mathcal{G})_x =
\mathcal{G}_{f(x)}
\otimes_{\mathcal{O}_{Y, f(x)}}
\mathcal{O}_{X, x}
$$
as $\mathcal{O}_{X, x}$-modules where the tensor product on the right
uses $f^\sharp_x : \mathcal{O}_{Y, f(x)} \to \mathcal{O}_{X, x}$.

\label{lemma-algebraic-extension-self-map}
Let $E/F$ an algebraic extension of fields. Any $F$-algebra map
$f : E \to E$ is an automorphism.

\label{lemma-normal-closure-inside-normal}
Let $L/K$ be an algebraic normal extension.
\begin{enumerate}
\item If $L/M/K$ is a subextension with $M/K$ finite, then there exists
a tower $L/M'/M/K$ with $M'/K$ finite and normal.
\item If $L/M'/M/K$ is a tower with $M/K$ normal and $M'/M$ finite,
then there exists a tower $L/M''/M'/M/K$ with $M''/M$
finite and $M''/K$ normal.
\end{enumerate}

\label{lemma-colimit-tensor-algebra}
\begin{slogan}
Taking tensor algebras commutes with filtered colimits.
\end{slogan}
Let $R$ be a ring. Let $M_i$ be a directed system of
$R$-modules. Then
$\colim_i \text{T}(M_i) = \text{T}(\colim_i M_i)$
and similarly for the symmetric and exterior algebras.

\label{lemma-topology-quasi-separated-scheme}
Let $X$ be a topological space which
\begin{enumerate}
\item has a basis of the topology consisting of quasi-compact opens, and
\item has the property that the intersection of any two quasi-compact
opens is quasi-compact.
\end{enumerate}
Then
\begin{enumerate}
\item $X$ is locally quasi-compact,
\item a quasi-compact open $U \subset X$ is retrocompact,
\item any quasi-compact open $U \subset X$ has a cofinal system of open
coverings $\mathcal{U} : U = \bigcup_{j\in J} U_j$ with $J$ finite
and all $U_j$ and $U_j \cap U_{j'}$ quasi-compact,
\item add more here.
\end{enumerate}

\label{lemma-qc-open}
Let $U \subset \Spec(R)$ be open. The following
are equivalent:
\begin{enumerate}
\item $U$ is retrocompact in $\Spec(R)$,
\item $U$ is quasi-compact,
\item $U$ is a finite union of standard opens, and
\item there exists a finitely generated ideal $I \subset R$ such
that $X \setminus V(I) = U$.
\end{enumerate}

\label{lemma-image-quasi-compact}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $X$ is quasi-compact, then $f(X)$ is quasi-compact.
\item If $f$ is quasi-compact, then $f(X)$ is retrocompact.
\end{enumerate}

\label{lemma-constructible-hausdorff-quasi-compact}
Let $X$ be a spectral space. The constructible topology is
Hausdorff, totally disconnected, and quasi-compact.

\label{lemma-finite-finite-type}
Let $\varphi : R \to S$ be a ring map.
\begin{enumerate}
\item If $\varphi$ is finite, then $\varphi$ is of finite type.
\item If $S$ is of finite presentation as an $R$-module, then
$\varphi$ is of finite presentation.
\end{enumerate}

\label{lemma-normality-is-local}
Let $R$ be a domain. The following are equivalent:
\begin{enumerate}
\item The domain $R$ is a normal domain,
\item for every prime $\mathfrak p \subset R$ the local ring
$R_{\mathfrak p}$ is a normal domain, and
\item for every maximal ideal $\mathfrak m$ the ring $R_{\mathfrak m}$
is a normal domain.
\end{enumerate}

\label{lemma-2-product-categories-fibred-sets}
Let $\mathcal{C}$ be a category.
The 2-category of categories fibred in sets over $\mathcal{C}$
has 2-fibre products. More precisely, the 2-fibre product described in
Lemma \ref{lemma-2-product-categories-over-C}
returns a category fibred in sets if one starts out with such.

\label{lemma-irreducible-components-containing-x}
Let $R$ be a ring. Let $\mathfrak p \subset R$ be a prime.
\begin{enumerate}
\item the set of irreducible closed subsets of $\Spec(R)$
passing through $\mathfrak p$ is in one-to-one correspondence with
primes $\mathfrak q \subset R_{\mathfrak p}$.
\item The set of irreducible components of $\Spec(R)$ passing through
$\mathfrak p$ is in one-to-one correspondence with minimal
primes $\mathfrak q \subset R_{\mathfrak p}$.
\end{enumerate}

\label{lemma-noetherian-partition-refined-by-stratification}
Let $X$ be a Noetherian topological space. Any finite partition
of $X$ can be refined by a finite good stratification.

\label{lemma-open-closed-specialization}
Let $X$ be a topological space.
\begin{enumerate}
\item Any closed subset of $X$ is stable under specialization.
\item Any open subset of $X$ is stable under generalization.
\item A subset $T \subset X$ is stable under specialization
if and only if
the complement $T^c$ is stable under generalization.
\end{enumerate}

\label{lemma-characterize-zero-local}
Let $R$ be a ring.
\begin{enumerate}
\item For an element $x$ of an $R$-module $M$ the following are equivalent
\begin{enumerate}
\item $x = 0$,
\item $x$ maps to zero in $M_\mathfrak p$ for all $\mathfrak p \in \Spec(R)$,
\item $x$ maps to zero in $M_{\mathfrak m}$ for all maximal ideals
$\mathfrak m$ of $R$.
\end{enumerate}
In other words, the map $M \to \prod_{\mathfrak m} M_{\mathfrak m}$
is injective.
\item Given an $R$-module $M$ the following are equivalent
\begin{enumerate}
\item $M$ is zero,
\item $M_{\mathfrak p}$ is zero for all $\mathfrak p \in \Spec(R)$,
\item $M_{\mathfrak m}$ is zero for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\item Given a complex $M_1 \to M_2 \to M_3$
of $R$-modules the following are equivalent
\begin{enumerate}
\item $M_1 \to M_2 \to M_3$ is exact,
\item for every prime $\mathfrak p$ of $R$ the localization
$M_{1, \mathfrak p} \to M_{2, \mathfrak p} \to M_{3, \mathfrak p}$
is exact,
\item for every maximal ideal $\mathfrak m$ of $R$ the localization
$M_{1, \mathfrak m} \to M_{2, \mathfrak m} \to M_{3, \mathfrak m}$
is exact.
\end{enumerate}
\item Given a map $f : M \to M'$ of $R$-modules the following are equivalent
\begin{enumerate}
\item $f$ is injective,
\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is injective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is injective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\item Given a map $f : M \to M'$ of $R$-modules the following are equivalent
\begin{enumerate}
\item $f$ is surjective,
\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is surjective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is surjective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\item Given a map $f : M \to M'$ of $R$-modules the following are equivalent
\begin{enumerate}
\item $f$ is bijective,
\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is bijective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is bijective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\end{enumerate}

\label{lemma-finite-closed-in-finite-finite-presentation}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is finite, and
\item $S$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a morphism which is finite and of finite presentation
$f' : X' \to S$ and a closed immersion $X \to X'$ of schemes over $S$.

\label{lemma-lift-idempotents}
Let $R$ be a ring. Let $I \subset R$ be a locally nilpotent ideal.
Then $R \to R/I$ induces a bijection on idempotents.

\label{lemma-characterize-closed-Noetherian}
Let $X$ be a Noetherian sober topological space.
Let $E \subset X$ be a subset of $X$.
\begin{enumerate}
\item If $E$ is constructible and stable under specialization, then
$E$ is closed.
\item If $E$ is constructible and stable under generalization, then
$E$ is open.
\end{enumerate}

\label{lemma-integral-transitive}
\begin{slogan}
A composition of integral ring maps is integral
\end{slogan}
Suppose that $R \to S$ and $S \to T$ are integral
ring maps. Then $R \to T$ is integral.

\label{lemma-existence-projective-cover}
\begin{slogan}
Every quasi-compact Hausdorff space has a canonical
extremally disconnected cover
\end{slogan}
Let $X$ be a quasi-compact Hausdorff space.
There exists a continuous surjection $X' \to X$ with $X'$
quasi-compact, Hausdorff, and extremally disconnected.
If we require that every proper closed subset of $X'$ does not
map onto $X$, then $X'$ is unique up to isomorphism.

\label{lemma-subring-of-local-ring}
Let $R$ be a ring and $\mathfrak p \subset R$ be a prime.
There exists an $f \in R$, $f \not \in \mathfrak p$ such
that $R_f \to R_\mathfrak p$ is injective in each of the
following cases
\begin{enumerate}
\item $R$ is a domain,
\item $R$ is Noetherian, or
\item $R$ is reduced and has finitely many minimal primes.
\end{enumerate}

\label{lemma-exact-adjoint}
Let $u$ be a left adjoint of $v$ as in Definition \ref{definition-adjoint}.
\begin{enumerate}
\item If $\mathcal{C}$ has finite colimits, then $u$ is right exact.
\item If $\mathcal{D}$ has finite limits, then $v$ is left exact.
\end{enumerate}

\label{lemma-algebraic-goes-up}
Let $K/E/F$ be a tower of field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is algebraic over $F$, then $\alpha$ is algebraic
over $E$.
\item If $K$ is algebraic over $F$, then $K$ is algebraic over $E$.
\end{enumerate}

\label{lemma-approximate}
Let $S$ be a quasi-compact and quasi-separated scheme. Let $V \subset S$
be a quasi-compact open. Let $I$ be a directed set
and let $(V_i, f_{ii'})$ be an inverse system of schemes over $I$
with affine transition maps, with each $V_i$ of finite type over $\mathbf{Z}$,
and with $V = \lim V_i$. Then there exist
\begin{enumerate}
\item a directed set $J$,
\item an inverse system of schemes $(S_j, g_{jj'})$ over $J$,
\item an order preserving map $\alpha : J \to I$,
\item open subschemes $V'_j \subset S_j$, and
\item isomorphisms $V'_j \to V_{\alpha(j)}$
\end{enumerate}
such that
\begin{enumerate}
\item the transition morphisms $g_{jj'} : S_j \to S_{j'}$ are affine,
\item each $S_j$ is of finite type over $\mathbf{Z}$,
\item $g_{jj'}^{-1}(V'_{j'}) = V'_j$,
\item $S = \lim S_j$ and $V = \lim V'_j$, and
\item the diagrams
$$
\vcenter{
\xymatrix{
V \ar[d] \ar[rd] \\
V'_j \ar[r] & V_{\alpha(j)}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
V'_j \ar[r] \ar[d] & V_{\alpha(j)} \ar[d] \\
V'_{j'} \ar[r] & V_{\alpha(j')}
}
}
$$
are commutative.
\end{enumerate}

\label{lemma-lift-maps}
Let $L/M/K$ be a tower of algebraic extensions.
\begin{enumerate}
\item If $M/K$ is normal, then any automorphism $\tau$ of $L/K$
induces an automorphism $\tau|_M : M \to M$.
\item If $L/K$ is normal, then any $K$-algebra map $\sigma : M \to L$
extends to an automorphism of $L$.
\end{enumerate}

\label{lemma-quotient}
Let $X$ be a topological space. Let $Y$ be a set and let $f : X \to Y$
be a surjective map of sets. The quotient topology on $Y$ is the
topology characterized by each of the following statements:
\begin{enumerate}
\item it is the strongest topology on $Y$ such that $f$ is continuous,
\item a subset $V$ of $Y$ is open if and only if $f^{-1}(V)$ is open,
\item a subset $Z$ of $Y$ is closed if and only if $f^{-1}(Z)$ is closed.
\end{enumerate}

\label{lemma-sober-local}
Let $X$ be a topological space and let $(X_i)_{i\in I}$ be a covering of $X$.
\begin{enumerate}
\item Suppose $X_i$ is locally closed in $X$ for every $i\in I$. Then, $X$ is
Kolmogorov if and only if $X_i$ is Kolmogorov for every $i\in I$.
\item Suppose $X_i$ is open in $X$ for every $i\in I$. Then, $X$ is
quasi-sober if and only if $X_i$ is quasi-sober for every $i\in I$.
\item Suppose $X_i$ is open in $X$ for every $i\in I$. Then, $X$ is sober if
and  only if $X_i$ is sober for every $i\in I$.
\end{enumerate}

\label{lemma-subscheme-of-separated-scheme}
Let $f : X \to S$ be a separated morphism.
Any locally closed subscheme $Z \subset X$ is separated over $S$.

\label{lemma-tensor-product-globally-generated}
\begin{slogan}
The tensor product of globally generated sheaves of modules is
globally generated.
\end{slogan}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$, $\mathcal{G}$ be sheaves of $\mathcal{O}_X$-modules.
If $\mathcal{F}$ and $\mathcal{G}$ are generated by global sections
then so is $\mathcal{F} \otimes_{\mathcal{O}_X} \mathcal{G}$.

\label{lemma-descend-finite-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a finite morphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is finite.

\label{lemma-inverse-limit-spectral-spaces-nonempty}
Let $\mathcal{I}$ be a cofiltered category. Let $i \mapsto X_i$ be a diagram
of spectral spaces such that for $a : j \to i$ in $\mathcal{I}$
the corresponding map $f_a : X_j \to X_i$ is spectral.
\begin{enumerate}
\item Given nonempty subsets $Z_i \subset X_i$ closed in the constructible
topology with $f_a(Z_j) \subset Z_i$ for all $a : j \to i$ in $\mathcal{I}$,
then $\lim Z_i$ is nonempty.
\item If each $X_i$ is nonempty, then $X = \lim X_i$ is nonempty.
\end{enumerate}

\label{lemma-map-cannot-be-injective}
\begin{slogan}
A map of finite free modules cannot be injective if the source has
rank bigger than the target.
\end{slogan}
Let $R$ be a nonzero ring. Let $n \geq 1$. Let $M$ be an $R$-module generated
by $< n$ elements. Then any $R$-module map $f : R^{\oplus n} \to M$ has a
nonzero kernel.

\label{lemma-algebraically-closed}
Let $F$ be a field. The following are equivalent
\begin{enumerate}
\item $F$ is algebraically closed,
\item every irreducible polynomial over $F$ is linear,
\item every nonconstant polynomial over $F$ has a root,
\item every nonconstant polynomial over $F$ is a product of linear factors.
\end{enumerate}

\label{lemma-fibres-spectral-map-quasi-compact}
Let $f : X \to Y$ be a spectral map of spectral spaces. Then
\begin{enumerate}
\item $f$ is continuous in the constructible topology,
\item the fibres of $f$ are quasi-compact, and
\item the image is closed in the constructible topology.
\end{enumerate}

\label{lemma-characterize-mono-epi}
Let $\mathcal{C}$ be a category, and let $f : X \to Y$ be
a morphism of $\mathcal{C}$. Then
\begin{enumerate}
\item $f$ is a monomorphism if and only if $X$ is the fibre
product $X \times_Y X$, and
\item $f$ is an epimorphism if and only if $Y$ is the pushout
$Y \amalg_X Y$.
\end{enumerate}

\label{lemma-finite-type-closed-in-finite-presentation}
Let $f : X \to S$ be a morphism of schemes.
Assume:
\begin{enumerate}
\item The morphism $f$ is of locally of finite type.
\item The scheme $X$ is quasi-compact and quasi-separated, and
\item The scheme $S$ is quasi-separated.
\end{enumerate}
Then there exists a morphism of finite presentation
$f' : X' \to S$ and a closed immersion $X \to X'$ of schemes over $S$.

\label{lemma-lift-specializations-valuative}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item Specializations lift along any base change of $f$
\item The morphism $f$ satisfies the existence part of the
valuative criterion.
\end{enumerate}

\label{theorem-nullstellensatz}
Let $k$ be a field.
\begin{enumerate}
\item
\label{item-finite-kappa}
For any maximal ideal $\mathfrak m \subset k[x_1, \ldots, x_n]$
the field extension $\kappa(\mathfrak m)/k$ is finite.
\item
\label{item-polynomial-ring-Jacobson}
Any radical ideal $I \subset k[x_1, \ldots, x_n]$
is the intersection of maximal ideals containing it.
\end{enumerate}
The same is true in any finite type $k$-algebra.

\label{lemma-eventually-affine}
Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of schemes
over $S$ with affine transition morphisms. Assume
\begin{enumerate}
\item $S$ quasi-compact and quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to S$ affine.
\end{enumerate}
Then $X_i \to S$ is affine for $i$ large enough.

\label{lemma-constructible-is-retrocompact}
Let $X$ be a topological space. Every constructible
subset of $X$ is retrocompact.

\label{lemma-from-hausdorff}
Let $f : X \to Y$ be continuous map of topological spaces.
If $X$ is Hausdorff, then $f$ is separated.

\label{lemma-product-ideals-in-prime}
Let $R$ be a ring, $I$ and $J$ two ideals and $\mathfrak p$ a prime ideal
containing the product $IJ$. Then $\mathfrak{p}$ contains $I$ or $J$.

\label{lemma-filtered-colimit-constructibles}
Let $X$ be a topological space. Let $\mathcal{B}$ be a basis for the
topology of $X$ and assume that each $U \in \mathcal{B}$ is quasi-compact.
Then every sheaf of sets on $X$ is a filtered colimit of sheaves of the form
\begin{equation}
\label{equation-towards-constructible-sets}
\text{Coequalizer}\left(
\xymatrix{
\coprod\nolimits_{b = 1, \ldots, m} j_{V_b!}\underline{S_b}
\ar@<1ex>[r] \ar@<-1ex>[r] &
\coprod\nolimits_{a = 1, \ldots, n} j_{U_a!}\underline{S_a}
}
\right)
\end{equation}
with $U_a$ and $V_b$ in $\mathcal{B}$ and $S_a$ and $S_b$ finite sets.

\label{lemma-size-algebraic-extension}
Let $E/F$ be an algebraic extension of fields. Then the cardinality $|E|$
of $E$ is at most $\max(\aleph_0, |F|)$.

\label{lemma-2-category-fibred-setoids}
Let $\mathcal{C}$ be a category. The construction of
Lemma \ref{lemma-setoid-fibres}
part (2) gives a functor
$$
F :
\left\{
\begin{matrix}
\text{the 2-category of categories}\\
\text{fibred in setoids over }\mathcal{C}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{the category of categories}\\
\text{fibred in sets over }\mathcal{C}
\end{matrix}
\right\}
$$
(see
Definition \ref{definition-functor-into-2-category}).
This functor is an equivalence in the following sense:
\begin{enumerate}
\item for any two 1-morphisms $f, g : \mathcal{S}_1 \to \mathcal{S}_2$
with $F(f) = F(g)$ there exists a unique 2-isomorphism $f \to g$,
\item for any morphism $h : F(\mathcal{S}_1) \to F(\mathcal{S}_2)$
there exists a 1-morphism $f : \mathcal{S}_1 \to \mathcal{S}_2$
with $F(f) = h$, and
\item any category fibred in sets $\mathcal{S}$ is equal to $F(\mathcal{S})$.
\end{enumerate}
In particular, defining $F_i \in \textit{PSh}(\mathcal{C})$ by the
rule $F_i(U) = \Ob(\mathcal{S}_{i, U})/\cong$, we have
$$
\Mor_{\textit{Cat}/\mathcal{C}}(\mathcal{S}_1, \mathcal{S}_2)
\Big/
2\text{-isomorphism}
=
\Mor_{\textit{PSh}(\mathcal{C})}(F_1, F_2)
$$
More precisely, given any map $\phi : F_1 \to F_2$ there exists a
$1$-morphism $f : \mathcal{S}_1 \to \mathcal{S}_2$ which induces
$\phi$ on isomorphism classes of objects and
which is unique up to unique $2$-isomorphism.

\label{lemma-cohen}
Let $R$ be a ring.
\begin{enumerate}
\item An ideal $I \subset R$ maximal with respect to not being
finitely generated is prime.
\item If every prime ideal of $R$ is
finitely generated, then
every ideal of $R$ is finitely generated\footnote{Later we will say
that $R$ is Noetherian.}.
\end{enumerate}

\label{lemma-colimits}
The category of topological spaces has colimits and the forgetful functor
to sets commutes with them.

\label{lemma-finite-finite-fibres}
Suppose $R \to S$ is finite.
Then the fibres of $\Spec(S) \to \Spec(R)$ are finite.

\label{lemma-directed-inverse-limit-finite-sober-spectral-spaces}
The inverse limit of a directed inverse system of finite sober
topological spaces is a spectral topological space.

\label{lemma-power-series-over-Noetherian-normal-domain}
Let $R$ be a Noetherian normal domain. Then $R[[x]]$ is
a Noetherian normal domain.

\label{lemma-going-up-down-specialization}
Let $R \to S$ be a ring map.
\begin{enumerate}
\item $R \to S$ satisfies going down if and only if
generalizations lift along the map $\Spec(S) \to \Spec(R)$,
see Topology, Definition \ref{topology-definition-lift-specializations}.
\item $R \to S$ satisfies going up if and only if
specializations lift along the map $\Spec(S) \to \Spec(R)$,
see Topology, Definition \ref{topology-definition-lift-specializations}.
\end{enumerate}

\label{lemma-kernel-surjection-finite-free-onto-finite-presentation}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module of finite presentation.
\begin{enumerate}
\item If $\psi : \mathcal{O}_X^{\oplus r} \to \mathcal{F}$ is a surjection,
then $\Ker(\psi)$ is of finite type.
\item If $\theta : \mathcal{G} \to \mathcal{F}$ is surjective with
$\mathcal{G}$ of finite type, then $\Ker(\theta)$ is of finite type.
\end{enumerate}

\label{lemma-properties-2-cat-cats}
The horizontal and vertical compositions have the following
properties
\begin{enumerate}
\item $\circ$ and $\star$ are associative,
\item the identity transformations $\text{id}_F$
are units for $\circ$,
\item the identity transformations of the identity functors
$\text{id}_{\text{id}_\mathcal{A}}$
are units for $\star$ and $\circ$, and
\item given a diagram
$$
\xymatrix{
\mathcal{A}
\rruppertwocell^F{t}
\ar[rr]_(.3){F'}
\rrlowertwocell_{F''}{t'}
& &
\mathcal{B}
\rruppertwocell^G{s}
\ar[rr]_(.3){G'}
\rrlowertwocell_{G''}{s'}
& &
\mathcal{C}
}
$$
we have $ (s' \circ s) \star (t' \circ t) = (s' \star t') \circ (s \star t)$.
\end{enumerate}

\label{lemma-almost-finite-colimits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Nonempty finite colimits exist in $\mathcal{C}$.
\item Coproducts of pairs and coequalizers exist in $\mathcal{C}$.
\item Coproducts of pairs and pushouts exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-top-cohomology-functor}
Let $f : X \to Y$ be a morphism of schemes. Let $d \geq 0$. Assume
\begin{enumerate}
\item $X$ and $Y$ are quasi-compact and quasi-separated, and
\item $R^if_*\mathcal{F} = 0$ for $i > d$ and
every quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$.
\end{enumerate}
Then we have
\begin{enumerate}
\item[(a)] for any base change diagram
$$
\xymatrix{
X' \ar[d]_{f'} \ar[r]_{g'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
$$
we have $R^if'_*\mathcal{F}' = 0$ for $i > d$ and any quasi-coherent
$\mathcal{O}_{X'}$-module $\mathcal{F}'$,
\item[(b)]
$R^df'_*(\mathcal{F}' \otimes_{\mathcal{O}_{X'}} (f')^*\mathcal{G}') =
R^df'_*\mathcal{F}' \otimes_{\mathcal{O}_{Y'}} \mathcal{G}'$
for any quasi-coherent $\mathcal{O}_{Y'}$-module $\mathcal{G}'$,
\item[(c)] formation of $R^df'_*\mathcal{F}'$ commutes with arbitrary
further base change (see proof for explanation).
\end{enumerate}

\label{lemma-normal-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
If $K$ is normal over $F$, then $K$ is normal over $E$.

\label{lemma-spectral-bijective}
Let $f : X \to Y$ be a continuous map of topological spaces. If
\begin{enumerate}
\item $X$ and $Y$ are spectral,
\item $f$ is spectral and bijective, and
\item generalizations (resp.\ specializations) lift along $f$.
\end{enumerate}
Then $f$ is a homeomorphism.

\label{lemma-inverse-limit-top}
\begin{reference}
\cite[IV, Proposition 8.2.9]{EGA}
\end{reference}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{lemma-directed-inverse-system-has-limit}). Then
$S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.

\label{lemma-spectral-inverse-limit-finite-sober-spaces}
A topological space is spectral if and only if it is a directed
inverse limit of finite sober topological spaces.

\label{lemma-injective-points-surjective-stalks}
Let $j : X \to Y$ be a morphism of schemes.
If
\begin{enumerate}
\item $j$ is injective on points, and
\item for any $x \in X$ the ring map
$j^\sharp_x : \mathcal{O}_{Y, j(x)} \to \mathcal{O}_{X, x}$
is surjective,
\end{enumerate}
then $j$ is a monomorphism.

\label{lemma-integral-permanence}
Let $A \to B \to C$ be ring maps.
\begin{enumerate}
\item If $A \to C$ is integral so is $B \to C$.
\item If $A \to C$ is finite so is $B \to C$.
\end{enumerate}

\label{lemma-algebraic-permanence}
Let $E/k$ and $F/E$ be algebraic extensions of fields. Then $F/k$ is an
algebraic extension of fields.

\label{lemma-Jacobson-invert-element}
Let $R$ be a Jacobson ring. Let $f \in R$. The ring $R_f$ is Jacobson and
maximal ideals of $R_f$ correspond to maximal ideals of $R$ not containing $f$.

\label{lemma-right-localization}
Let $\mathcal{C}$ be a category and let $S$ be a right multiplicative
system.
\begin{enumerate}
\item The relation on pairs defined above is an equivalence relation.
\item The composition rule given above is well defined on equivalence
classes.
\item Composition is associative (and the identity morphisms satisfy
the identity axioms), and hence $S^{-1}\mathcal{C}$ is a category.
\end{enumerate}

\label{lemma-basis-affine-opens}
Let $X$ be a scheme. The collection of affine opens
of $X$ forms a basis for the topology on $X$.

\label{lemma-characterize-finite-in-terms-of-integral}
Let $R \to S$ be a ring map. The following are equivalent
\begin{enumerate}
\item $R \to S$ is finite,
\item $R \to S$ is integral and of finite type, and
\item there exist $x_1, \ldots, x_n \in S$ which generate $S$ as an
algebra over $R$ such that each $x_i$ is integral over $R$.
\end{enumerate}

\label{lemma-eventually-proper}
\begin{slogan}
If the base change of a scheme to a limit is proper, then
already the base change is proper at a finite level.
\end{slogan}
Assumptions and notation as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is proper, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i$ such that $f_i$ is proper.

\label{lemma-left-adjoint-composed-fully-faithful}
\begin{reference}
Bhargav Bhatt, private communication.
\end{reference}
Let $u$ be a left adjoint to $v$ as in Definition \ref{definition-adjoint}.
\begin{enumerate}
\item If $v \circ u$ is fully faithful, then $u$ is fully faithful.
\item If $u \circ v$ is fully faithful, then $v$ is fully faithful.
\end{enumerate}

\label{theorem-characterize-proper}
\begin{reference}
In \cite[I, p. 75, Theorem 1]{Bourbaki} you can find:
(2) $\Leftrightarrow$ (4).
In \cite[I, p. 77, Proposition 6]{Bourbaki} you can find:
(2) $\Rightarrow$ (1).
\end{reference}
Let $f: X\to Y$ be a continuous map between
topological spaces. The following conditions are equivalent:
\begin{enumerate}
\item The map $f$ is quasi-proper and closed.
\item The map $f$ is Bourbaki-proper.
\item The map $f$ is universally closed.
\item The map $f$ is closed and $f^{-1}(y)$ is quasi-compact for any
$y\in Y$.
\end{enumerate}

\label{lemma-morphism-good-diagram}
In Situation \ref{situation-limit-noetherian}.
Let $f : X \to Y$ be a morphism of schemes quasi-separated
and of finite type over $S$. Let
$$
\vcenter{
\xymatrix{
X \ar[r] \ar[d] & W \ar[d] \\
S \ar[r] & S_{i_1}
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
Y \ar[r] \ar[d] & V \ar[d] \\
S \ar[r] & S_{i_2}
}
}
$$
be diagrams as in (\ref{equation-good-diagram}). Let
$X = \lim_{i \geq i_1} X_i$ and
$Y = \lim_{i \geq i_2} Y_i$ be the corresponding
limit descriptions as in Lemma \ref{lemma-limit-from-good-diagram}.
Then there exists an $i_0 \geq \max(i_1, i_2)$ and a morphism
$$
(f_i)_{i \geq i_0} : (X_i)_{i \geq i_0} \to (Y_i)_{i \geq i_0}
$$
of inverse systems over $(S_i)_{i \geq i_0}$ such that
such that $f = \lim_{i \geq i_0} f_i$.
If $(g_i)_{i \geq i_0} : (X_i)_{i \geq i_0} \to (Y_i)_{i \geq i_0}$
is a second morphism of inverse systems over $(S_i)_{i \geq i_0}$ such that
such that $f = \lim_{i \geq i_0} g_i$
then $f_i = g_i$ for all $i \gg i_0$.

\label{lemma-characterize-representable-fibred-category}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category fibred in groupoids.
\begin{enumerate}
\item $\mathcal{S}$ is representable if and only if
the following conditions are satisfied:
\begin{enumerate}
\item $\mathcal{S}$ is fibred in setoids, and
\item the presheaf $U \mapsto \Ob(\mathcal{S}_U)/\cong$ is
representable.
\end{enumerate}
\item If $\mathcal{S}$ is representable the pair $(X, j)$, where $j$ is the
equivalence $j : \mathcal{S} \to \mathcal{C}/X$, is uniquely determined
up to isomorphism.
\end{enumerate}

\label{lemma-integral-local}
Let $R \to S$ be a ring map.
Let $f_1, \ldots, f_n \in R$ generate the unit ideal.
\begin{enumerate}
\item If each $R_{f_i} \to S_{f_i}$ is integral, so is $R \to S$.
\item If each $R_{f_i} \to S_{f_i}$ is finite, so is $R \to S$.
\end{enumerate}

\label{lemma-Noetherian-quasi-compact}
Let $X$ be a Noetherian topological space.
\begin{enumerate}
\item The space $X$ is quasi-compact.
\item Any subset of $X$ is retrocompact.
\end{enumerate}

\label{lemma-image-Noetherian}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $X$ is Noetherian, then $f(X)$ is Noetherian.
\item If $X$ is locally Noetherian and $f$ open, then $f(X)$ is
locally Noetherian.
\end{enumerate}

\label{lemma-profinite}
Let $X$ be a topological space.
The following are equivalent
\begin{enumerate}
\item $X$ is a profinite space, and
\item $X$ is Hausdorff, quasi-compact, and totally disconnected.
\end{enumerate}
If this is true, then $X$ is a cofiltered limit of finite discrete
spaces.

\label{lemma-characterize-finite-module-hom}
Let $R$ be a ring. Let $N$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $N$ is a finite $R$-module,
\item for any filtered colimit $M = \colim M_i$ of $R$-modules the map
$\colim \Hom_R(N, M_i) \to \Hom_R(N, M)$ is injective.
\end{enumerate}

\label{lemma-ff}
\begin{slogan}
A flat module is faithfully flat if and only if it has nonzero fibers.
\end{slogan}
Let $M$ be a flat $R$-module.
The following are equivalent:
\begin{enumerate}
\item $M$ is faithfully flat,
\item for every nonzero $R$-module $N$, then tensor product $M \otimes_R N$
is nonzero,
\item for all $\mathfrak p \in \Spec(R)$
the tensor product $M \otimes_R \kappa(\mathfrak p)$ is nonzero, and
\item for all maximal ideals $\mathfrak m$ of $R$
the tensor product $M \otimes_R \kappa(\mathfrak m) = M/{\mathfrak m}M$
is nonzero.
\end{enumerate}

\label{lemma-integral-closure-stalks}
\begin{slogan}
An element of an algebra over a ring is integral over the ring
if and only if it is locally integral at every prime ideal of the ring.
\end{slogan}
Let $\varphi : R \to S$ be a ring map.
Let $x \in S$. The following are equivalent:
\begin{enumerate}
\item $x$ is integral over $R$, and
\item for every prime ideal $\mathfrak p \subset R$ the element
$x \in S_{\mathfrak p}$ is integral over $R_{\mathfrak p}$.
\end{enumerate}

\label{lemma-affine-reduced}
An affine scheme $\Spec(R)$ is reduced
if and only if $R$ is reduced.

\label{lemma-quasi-compact}
\begin{slogan}
The spectrum of a ring is quasi-compact
\end{slogan}
Let $R$ be a ring. The space $\Spec(R)$ is quasi-compact.

\label{theorem-uncountable-nullstellensatz}
Let $k$ be a field. Let $S$ be a $k$-algebra generated over $k$
by the elements $\{x_i\}_{i \in I}$. Assume the cardinality of $I$
is smaller than the cardinality of $k$. Then
\begin{enumerate}
\item for all maximal ideals $\mathfrak m \subset S$ the field
extension $\kappa(\mathfrak m)/k$
is algebraic, and
\item $S$ is a Jacobson ring.
\end{enumerate}

\label{lemma-flat-eq}
Let $(X, \mathcal{O}_X)$ be a ringed space. Let $\mathcal{F}$ be a flat
$\mathcal{O}_X$-module. Let $U \subset X$ be open and let
$$
\mathcal{O}_U \xrightarrow{(f_1, \ldots, f_n)}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. For every $x \in U$ there
exists an open neighbourhood $V \subset U$ of $x$ and a factorization
$$
\mathcal{O}_V^{\oplus n}
\xrightarrow{A}
\mathcal{O}_V^{\oplus m} \xrightarrow{(t_1, \ldots, t_m)}
\mathcal{F}|_V
$$
of $(s_1, \ldots, s_n)|_V$ such that $A \circ (f_1, \ldots, f_n)|_V = 0$.

\label{lemma-free-tensor-algebra}
Let $R$ be a ring. Let $M$ be an $R$-module.
If $M$ is a free $R$-module, so is each symmetric and exterior power.

\label{lemma-limit-quasi-affine}
In Situation \ref{situation-descent} if $S$ is quasi-affine, then
for some $i_0 \in I$ the schemes $S_i$ for $i \geq i_0$ are quasi-affine.

\label{lemma-lift-nth-roots}
Let $R$ be a ring. Let $I \subset R$ be a locally nilpotent ideal.
Let $n \geq 1$ be an integer which is invertible in $R/I$. Then
\begin{enumerate}
\item the $n$th power map $1 + I \to 1 + I$, $1 + x \mapsto (1 + x)^n$
is a bijection,
\item a unit of $R$ is a $n$th power if and only if its image in $R/I$
is an $n$th power.
\end{enumerate}

\label{lemma-equivalence-categories}
A functor is an equivalence of categories if and only if it is both fully
faithful and essentially surjective.

\label{lemma-limits}
The category of topological spaces has limits and the forgetful functor
to sets commutes with them.

\label{lemma-inverse-limit-spectral-spaces-quasi-compact}
Let $\mathcal{I}$ be a category. Let $i \mapsto X_i$ be a diagram
of spectral spaces such that for $a : j \to i$ in $\mathcal{I}$
the corresponding map $f_a : X_j \to X_i$ is spectral.
\begin{enumerate}
\item Given subsets $Z_i \subset X_i$ closed in the constructible
topology with $f_a(Z_j) \subset Z_i$ for all $a : j \to i$ in $\mathcal{I}$,
then $\lim Z_i$ is quasi-compact.
\item The space $X = \lim X_i$ is quasi-compact.
\end{enumerate}

\label{lemma-fibre-product-after-map}
Let $\mathcal{A} \to \mathcal{C}$, $\mathcal{B} \to \mathcal{C}$
and $\mathcal{C} \to \mathcal{D}$ be functors between categories.
Then the diagram
$$
\xymatrix{
\mathcal{A} \times_\mathcal{C} \mathcal{B} \ar[d] \ar[r] &
\mathcal{A} \times_\mathcal{D} \mathcal{B} \ar[d] \\
\mathcal{C} \ar[r]^-{\Delta_{\mathcal{C}/\mathcal{D}}} \ar[r] &
\mathcal{C} \times_\mathcal{D} \mathcal{C}
}
$$
is a $2$-fibre product diagram.

\label{lemma-compose-f-maps-stalks}
Suppose that $f : X \to Y$ and $g : Y \to Z$ are continuous
maps of topological spaces. Suppose that $\mathcal{F}$ is
a sheaf on $X$, $\mathcal{G}$ is a sheaf on $Y$, and
$\mathcal{H}$ is a sheaf on $Z$.
Let $\varphi : \mathcal{G} \to \mathcal{F}$ be an $f$-map.
Let $\psi : \mathcal{H} \to \mathcal{G}$ be an $g$-map.
Let $x \in X$ be a point. The map on stalks
$(\varphi \circ \psi)_x : \mathcal{H}_{g(f(x))}
\to \mathcal{F}_x$ is the composition
$$
\mathcal{H}_{g(f(x))}
\xrightarrow{\psi_{f(x)}}
\mathcal{G}_{f(x)}
\xrightarrow{\varphi_x}
\mathcal{F}_x
$$

\label{lemma-descend-closed-immersion-finite-presentation}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a closed immersion, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is a closed immersion.

\label{lemma-quasi-compact-in-Hausdorff}
Let $X$ be a Hausdorff topological space.
\begin{enumerate}
\item If $E \subset X$ is quasi-compact, then it is closed.
\item If $E_1, E_2 \subset X$ are disjoint quasi-compact subsets
then there exists opens $E_i \subset U_i$ with $U_1 \cap U_2 = \emptyset$.
\end{enumerate}

\label{lemma-prepare-polynomial-ring-normal}
Let $R$ be a domain with fraction field $K$.
Suppose $f = \sum \alpha_i x^i$ is an
element of $K[x]$.
\begin{enumerate}
\item If $f$ is integral over $R[x]$
then all $\alpha_i$ are integral over $R$, and
\item If $f$ is almost integral over $R[x]$
then all $\alpha_i$ are almost integral over $R$.
\end{enumerate}

\label{lemma-diagonal-immersion}
\begin{slogan}
The diagonal morphism for relative schemes is an immersion.
\end{slogan}
Let $X$ be a scheme over $S$.
The diagonal morphism $\Delta_{X/S}$ is an immersion.

\label{lemma-compose-after-separated}
\begin{slogan}
Separated and quasi-separated morphisms satisfy cancellation.
\end{slogan}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of schemes.
If $g \circ f$ is separated then so is $f$.
If $g \circ f$ is quasi-separated then so is $f$.

\label{lemma-separable-first}
\begin{slogan}
Any algebraic field extension is uniquely a separable field extension
followed by a purely inseparable one.
\end{slogan}
Let $E/F$ be an algebraic field extension. There exists a unique subextension
$E/E_{sep}/F$ such that $E_{sep}/F$ is separable and $E/E_{sep}$ is
purely inseparable.

\label{lemma-proper-top-cohomology-finite-presentation}
Let $f : X \to Y$ be a morphism of schemes. Let $d \geq 0$.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module. Assume
\begin{enumerate}
\item $f$ is a proper morphism of finite presentation
all of whose fibres have dimension $\leq d$,
\item $\mathcal{F}$ is an $\mathcal{O}_X$-module of finite presentation.
\end{enumerate}
Then $R^df_*\mathcal{F}$ is an $\mathcal{O}_X$-module
of finite presentation.

\label{lemma-finite-in-finite-and-finite-presentation}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is finite, and
\item $S$ quasi-compact and quasi-separated.
\end{enumerate}
Then $X$ is a directed limit $X = \lim X_i$
where the transition maps are closed immersions and the objects
$X_i$ are finite and of finite presentation over $S$.

\label{lemma-Noetherian}
Let $X$ be a Noetherian topological space.
\begin{enumerate}
\item Any subset of $X$ with the induced topology is Noetherian.
\item The space $X$ has finitely many irreducible components.
\item Each irreducible component of $X$ contains a nonempty open of $X$.
\end{enumerate}

\label{lemma-intersect-constructible-with-retrocompact}
Let $X$ be a topological space. Let $T \subset X$ be a subset. Suppose
\begin{enumerate}
\item $T$ is retrocompact in $X$,
\item quasi-compact opens form a basis for the topology on $X$.
\end{enumerate}
Then for a constructible set $E \subset X$ the intersection $E \cap T$ is
constructible in $T$.

\label{lemma-characterize-quasi-compact}
\begin{reference}
Combination of
\cite[I, p. 75, Lemme 1]{Bourbaki} and
\cite[I, p. 76, Corrolaire 1]{Bourbaki}.
\end{reference}
A topological space $X$ is quasi-compact if and only if the
projection map $Z \times X \to Z$ is closed for
any topological space $Z$.

\label{lemma-glueing-near-closed-point}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\begin{matrix}
X \to S\text{ of finite presentation}
\end{matrix}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

\label{lemma-primitive-element}
Let $E/F$ be a finite extension of fields. The following are equivalent
\begin{enumerate}
\item there exists a primitive element for $E$ over $F$, and
\item there are finitely many subextensions $E/K/F$.
\end{enumerate}
Moreover, (1) and (2) hold if $E/F$ is separable.

\label{lemma-dimension-supremum-local-dimensions}
Let $X$ be a topological space. Then $\dim(X) = \sup \dim_x(X)$
where the supremum runs over the points $x$ of $X$.

\label{lemma-flat-base-change}
Suppose that $M$ is (faithfully) flat over $R$, and that $R \to R'$
is a ring map. Then $M \otimes_R R'$ is (faithfully) flat over $R'$.

\label{lemma-glue-modules}
Let $R$ be a ring. Let $f_1, \ldots, f_n \in R$. Suppose we are given
the following data:
\begin{enumerate}
\item For each $i$ an $R_{f_i}$-module $M_i$.
\item For each pair $i, j$ an $R_{f_if_j}$-module isomorphism
$\psi_{ij} : (M_i)_{f_j} \to (M_j)_{f_i}$.
\end{enumerate}
which satisfy the ``cocycle condition'' that all the diagrams
$$
\xymatrix{
(M_i)_{f_jf_k}
\ar[rd]_{\psi_{ij}}
\ar[rr]^{\psi_{ik}}
& &
(M_k)_{f_if_j} \\
&
(M_j)_{f_if_k} \ar[ru]_{\psi_{jk}}
}
$$
commute (for all triples $i, j, k$). Given this data define
$$
M = \Ker\left(
\bigoplus\nolimits_{1 \leq i \leq n} M_i
\longrightarrow
\bigoplus\nolimits_{1 \leq i, j \leq n} (M_i)_{f_j}
\right)
$$
where $(m_1, \ldots, m_n)$ maps to the element whose
$(i, j)$th entry is $m_i/1 - \psi_{ji}(m_j/1)$.
Then the natural map $M \to M_i$ induces an isomorphism
$M_{f_i} \to M_i$. Moreover $\psi_{ij}(m/1) = m/1$
for all $m \in M$ (with obvious notation).

\label{proposition-localization-exact}
\begin{slogan}
Localization is exact.
\end{slogan}
Let $L\xrightarrow{u} M\xrightarrow{v} N$ be an exact sequence
of $R$-modules. Then
$S^{-1}L \to S^{-1}M \to S^{-1}N$ is also exact.

\label{lemma-silly}
\begin{slogan}
1. In an affine scheme if a finite number of points are contained in an
open subset then they are contained in a smaller principal open subset.
2. Affine opens are cofinal among the neighborhoods of a given finite set
of an affine scheme
\end{slogan}
Let $R$ be a ring. Let $I_i \subset R$, $i = 1, \ldots, r$,
and $J \subset R$ be ideals. Assume
\begin{enumerate}
\item $J \not\subset I_i$ for $i = 1, \ldots, r$, and
\item all but two of $I_i$ are prime ideals.
\end{enumerate}
Then there exists an $x \in J$, $x\not\in I_i$ for all $i$.

\label{proposition-localize-twice}
Let $\overline{S}$ be the image of $S$ in $S'^{-1}A$, then
$(SS')^{-1}A$ is isomorphic to $\overline{S}^{-1}(S'^{-1}A)$.

\label{lemma-colimit-flat}
Let $R$ be a ring. Let $\{M_i, \varphi_{ii'}\}$ be a directed system of
flat $R$-modules. Then $\colim_i M_i$ is a flat $R$-module.

\label{lemma-matrix-left-inverse}
Let $R$ be a ring. Let $n \geq m$. Let $A$ be an
$n \times m$ matrix with coefficients in $R$. Let $J \subset R$
be the ideal generated by the $m \times m$ minors of $A$.
\begin{enumerate}
\item For any $f \in J$ there exists a $m \times n$ matrix $B$
such that $BA = f 1_{m \times m}$.
\item If $f \in R$ and $BA = f 1_{m \times m}$ for some $m \times n$ matrix
$B$, then $f^m \in J$.
\end{enumerate}

\label{lemma-connected-fibres-quotient-topology-connected-components}
Let $f : X \to Y$ be a continuous map of topological spaces.
Assume that
\begin{enumerate}
\item all fibres of $f$ are connected, and
\item a set $T \subset Y$ is closed if and only if $f^{-1}(T)$ is closed.
\end{enumerate}
Then $f$ induces a bijection between the sets of connected
components of $X$ and $Y$.

\label{lemma-topological-group-colimits}
The category of topological groups has colimits and colimits commute
with the forgetful functor to the category of groups.

\label{lemma-galois-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
If $K$ is Galois over $F$, then $K$ is Galois over $E$.

\label{lemma-topology-spec}
Let $R$ be a ring.
The topology on $X = \Spec(R)$ has the following properties:
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of any two quasi-compact opens is quasi-compact.
\end{enumerate}

\label{lemma-separated}
Let $f : X \to Y$ be continuous map of topological spaces.
The following are equivalent:
\begin{enumerate}
\item $f$ is separated,
\item $\Delta(X) \subset X \times_Y X$ is a closed subset,
\item given distinct points $x, x' \in X$ mapping to the same point of
$Y$, there exist disjoint open neighbourhoods of $x$ and $x'$.
\end{enumerate}

\label{lemma-characterize-fibred-setoids-inertia}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category fibred in groupoids.
The following are equivalent:
\begin{enumerate}
\item $p : \mathcal{S} \to \mathcal{C}$ is a category fibred in setoids, and
\item the canonical $1$-morphism $\mathcal{I}_\mathcal{S} \to \mathcal{S}$,
see (\ref{equation-inertia-structure-map}), is an equivalence (of categories
over $\mathcal{C}$).
\end{enumerate}

\label{lemma-descend-unramified}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is unramified, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then there exists an $i \geq 0$ such that $f_i$ is unramified.

\label{lemma-monomorphism}
\begin{slogan}
A scheme morphism is a monomorphism iff its diagonal is an isomorphism.
\end{slogan}
Let $j : X \to Y$ be a morphism of schemes.
Then $j$ is a monomorphism if and only if the
diagonal morphism $\Delta_{X/Y} : X \to X \times_Y X$ is
an isomorphism.

\label{lemma-quasi-compact-preserved-base-change}
Being quasi-compact is a property of morphisms of schemes
over a base which is preserved under arbitrary base change.

\label{lemma-finite-Galois}
Let $E/F$ be a finite extension of fields. Then $E$ is Galois over $F$
if and only if $|\text{Aut}(E/F)| = [E : F]$.

\label{lemma-constructible-stable-specialization-closed}
Let $X$ be a spectral space. Let $E \subset X$ be a subset closed
in the constructible topology (for example constructible).
\begin{enumerate}
\item If $x \in \overline{E}$, then $x$ is the specialization of a point of
$E$.
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E' \subset X$ is open in the constructible topology
(for example constructible) and stable under generalization, then $E'$ is open.
\end{enumerate}

\label{lemma-rephrase}
Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
Let $F'$ be a sheaf on $(\Sch/S')_{fppf}$.
The following are equivalent:
\begin{enumerate}
\item The restriction $F'|_{(\Sch/S)_{fppf}}$
is an algebraic space over $S$, and
\item the sheaf $h_S \times F'$ is an algebraic space over $S'$.
\end{enumerate}

\label{lemma-transcendence-degree}
Let $E/F$ be a field extension. A transcendence basis of $E$ over $F$ exists.
Any two transcendence bases have the same cardinality.

\label{proposition-separated-closed-in-finite-presentation}
Let $f : X \to S$ be a morphism of schemes. Assume
\begin{enumerate}
\item $f$ is of finite type and separated, and
\item $S$ is quasi-compact and quasi-separated.
\end{enumerate}
Then there exists a separated morphism of finite presentation
$f' : X' \to S$ and a closed immersion $X \to X'$ of schemes over $S$.

\label{lemma-skyscraper-stalks}
Let $X$ be a topological space, $x \in X$ a point, and
$A$ a set. For any point $x' \in X$ the stalk of the
skyscraper sheaf at $x$ with value $A$ at $x'$ is
$$
(i_{x, *}A)_{x'} =
\left\{
\begin{matrix}
A & \text{if} & x' \in \overline{\{x\}} \\
\{*\} & \text{if} & x' \not\in \overline{\{x\}}
\end{matrix}
\right.
$$
A similar description holds for the case of
abelian groups, algebraic structures and
sheaves of modules.

\label{lemma-descend-etale}
Notation and assumptions as in Situation \ref{situation-descent-property}.
If
\begin{enumerate}
\item $f$ is \'etale,
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is \'etale for some $i \geq 0$.

\label{lemma-quasi-compact-affine}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f : X \to S$ is quasi-compact,
\item the inverse image of every affine open is quasi-compact, and
\item there exists some affine open covering $S = \bigcup_{i \in I} U_i$
such that $f^{-1}(U_i)$ is quasi-compact for all $i$.
\end{enumerate}

\label{lemma-Noetherian-power}
\begin{slogan}
An ideal in a Noetherian ring is nilpotent if each element
of the ideal is nilpotent.
\end{slogan}
Let $R$ be a Noetherian ring. Let $I, J$ be ideals of $R$.
Suppose $J \subset \sqrt{I}$. Then $J^n \subset I$ for some $n$.
In particular, in a Noetherian ring the notions of
``locally nilpotent ideal''
and ``nilpotent ideal'' coincide.

\label{lemma-ideal-in-localization}
\begin{slogan}
Ideals in the localization of a ring are localizations of ideals.
\end{slogan}
Each ideal $I'$ of $S^{-1}A$ takes the form $S^{-1}I$, where one can
take $I$ to be the inverse image of $I'$ in $A$.

\label{lemma-category-of-spaces-over-smaller-base-scheme}
Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
The construction above give an equivalence of
categories
$$
\left\{
\begin{matrix}
\text{category of algebraic}\\
\text{spaces over }S
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{category of pairs }(F', F' \to S)\text{ consisting}\\
\text{of an algebraic space }F'\text{ over }S'\text{ and a}\\
\text{morphism }F' \to S\text{ of algebraic spaces over }S'
\end{matrix}
\right\}
$$

\label{lemma-closed-immersion-affine-case}
\begin{slogan}
For affine schemes, closed immersions correspond to ideals.
\end{slogan}
Let $(X, \mathcal{O}_X) = (\Spec(R), \mathcal{O}_{\Spec(R)})$
be an affine scheme. Let $i : Z \to X$ be any closed immersion
of locally ringed spaces. Then there exists a unique ideal
$I \subset R$ such that the morphism $i : Z \to X$ can be identified
with the closed immersion $\Spec(R/I) \to \Spec(R)$
constructed in Example \ref{example-closed-immersion-affines} above.

\label{lemma-rank}
\begin{slogan}
The rank of a finite free module is well defined.
\end{slogan}
Let $R$ be a nonzero ring. Let $n, m \geq 0$ be integers.
If $R^{\oplus n}$ is isomorphic to $R^{\oplus m}$ as
$R$-modules, then $n = m$.

\label{lemma-going-up-down-composition}
Suppose $R \to S$ and $S \to T$ are ring maps satisfying
going down. Then so does $R \to T$. Similarly for going up.

\label{lemma-finite-finitely-generated}
A finite extension of fields is a finitely generated field extension.
The converse is not true.

\label{lemma-count-embeddings-explicitly}
In Situation \ref{situation-finitely-generated} we have
$|\Mor_F(K, \overline{F})| = \prod_{i = 1}^n \deg_s(P_i)$.

\label{lemma-proper-top-cohomology-finite-type}
Let $f : X \to Y$ be a morphism of schemes. Let $d \geq 0$. Let $\mathcal{F}$
be an $\mathcal{O}_X$-module. Assume
\begin{enumerate}
\item $f$ is a proper morphism all of whose fibres have dimension $\leq d$,
\item $\mathcal{F}$ is a quasi-coherent $\mathcal{O}_X$-module of finite type.
\end{enumerate}
Then $R^df_*\mathcal{F}$ is a quasi-coherent $\mathcal{O}_X$-module
of finite type.

\label{lemma-closed-open-map-specialization}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $f$ is closed then specializations lift along $f$.
\item If $f$ is open, $X$ is a Noetherian topological space,
each irreducible closed subset of $X$ has a generic point,
and $Y$ is Kolmogorov then generalizations lift along $f$.
\end{enumerate}

\label{lemma-tensor-product-exact}
Let
\begin{align*}
M_1\xrightarrow{f} M_2\xrightarrow{g} M_3 \to 0
\end{align*}
be an exact sequence of $R$-modules and homomorphisms, and let $N$ be any
$R$-module. Then the sequence
\begin{equation}
\label{equation-2ndex}
M_1\otimes N\xrightarrow{f \otimes 1} M_2\otimes N \xrightarrow{g \otimes 1}
M_3\otimes N \to 0
\end{equation}
is exact. In other words, the functor $- \otimes_R N$ is
{\it right exact}, in the sense that tensoring
each term in the original right exact sequence preserves the exactness.
